// 云忍者 — 2026 ACP DevOps 大纲补充题库（7 大域共 140 题）
// 覆盖：云效DevOps平台、容器服务ACK、容器镜像ACR、
//       IaC与运维编排（ROS/Terraform/OOS）、可观测与监控（SLS/ARMS/Prometheus）、
//       发布与部署策略（滚动/蓝绿/灰度/流水线质量门禁）、微服务与服务治理（MSE/ASM）
// 格式与 questions-rds.js 完全一致：
//   {id, module, type:'single|multi|judge', question, options, answer:[idx...], explanation, ref}
//   id 前缀：yx/ack/acr/iac/obs/rel/mse，对应 7 主域；ref 统一为 help.aliyun.com/...（无 https:// 前缀）
//   judge 固定 options:["正确","错误"]；multi 答案为索引数组

const DEVOPS_QUESTIONS = [
  // ========== 1. 云效DevOps平台 yx01~22（10 单 + 9 多 + 3 判） ==========
  {id:'yx01',module:'云效DevOps平台',type:'single',question:'在阿里云云效 Codeup 中采用分支协作模型，若团队希望主干保持随时可发布、通过短生命周期特性分支 + 小步快合来减少合并冲突，应优先选择以下哪种模式？',options:['GitFlow 严格 develop/release/hotfix 多分支模型','Trunk-based Development（基于主干开发 + 功能分支或功能开关）','主干禁止任何合并，所有功能直接在 master 上 push','仅使用 tag 管理版本，不使用任何分支'],answer:[1],explanation:'Trunk-based Development 强调主干稳定可发布、特性分支生命周期短、合入频率高、配合功能开关，能显著降低 GitFlow 长分支合并成本；Codeup 的主干保护、MR 门禁与小步快合正是 Trunk-based 的最佳实践，适合追求持续交付的现代 DevOps 团队。',ref:'help.aliyun.com/zh/codeup/user-guide/branch-management/'},
  {id:'yx02',module:'云效DevOps平台',type:'single',question:'阿里云云效 Codeup 的 Code Owners（代码所有者）功能，关于其生效场景，以下哪项描述是正确的？',options:['Code Owners 只影响仓库展示页面，不会对 MR 审批产生任何实际约束','可在 CODEOWNERS 文件中按目录或文件模式指定必须审批的所有者，MR 涉及对应文件时需其审批方可合并','Code Owners 必须由每个 MR 提交人手动选择审批人，系统不自动识别','Code Owners 仅企业主账号可配置，子账号/成员无法查看或审批'],answer:[1],explanation:'Codeup 的 Code Owners 通过仓库根目录的 CODEOWNERS 文件声明负责方，支持按 Glob 路径、目录、扩展名精确匹配，当 MR 变更涉及被声明的文件时，系统会自动要求对应 Owner 作为审批人之一进行审批，从而保障核心代码、配置与敏感目录的变更合规受控。',ref:'help.aliyun.com/zh/codeup/user-guide/code-owners/'},
  {id:'yx03',module:'云效DevOps平台',type:'multi',question:'关于阿里云云效 Codeup 的代码库保护规则，以下哪些是官方默认支持且推荐用于主干保护的能力？',options:['Push 限制（仅允许特定成员或通过合并请求合入）','合并请求（MR）必须至少通过 N 个评审人审批','合并前必须通过 CI 流水线构建与代码质量门禁','合并前必须在本地执行一次代码格式化提交'],answer:[0,1,2],explanation:'Codeup 主干保护支持 Push 限制、MR 审批人数量门槛、CI 检查门禁（必须通过流水线任务才能合并）三大基础能力，A/B/C 正确。D 所述"本地必须执行格式化再提交"是团队约定，Codeup 可以通过流水线阶段强制检查格式化产物，但并非平台内建的"保护规则"开关。',ref:'help.aliyun.com/zh/codeup/user-guide/protect-a-branch/'},
  {id:'yx04',module:'云效DevOps平台',type:'judge',question:'阿里云云效 Codeup 内置的敏感信息扫描能力，可对 AK/SK、账号密码、私钥等密钥类内容做提交前与 MR 级检测，但一旦代码被推送成功后就无法再做全量历史回溯扫描。',options:['正确','错误'],answer:[1],explanation:'Codeup 敏感信息扫描不仅支持实时扫描（pre-receive 钩子、MR 新增变更检查），还支持对整个仓库历史提交进行全量回溯扫描，并可联动阻断推送或提示替换泄漏凭证，防止历史遗留密钥被攻击者检出。',ref:'help.aliyun.com/zh/codeup/user-guide/sensitive-information-detection/'},
  {id:'yx05',module:'云效DevOps平台',type:'single',question:'在阿里云云效 Codeup 中遇到代码仓库中含有大量模型文件、二进制安装包等大文件导致 clone 缓慢、仓库膨胀时，官方推荐使用以下哪项能力来管理大文件？',options:['直接把大文件放进仓库，靠多次 commit 覆盖以减少体积','启用 Git LFS（Large File Storage），将大文件指针存入 Git 而真实文件存于 LFS 存储后端','删除 .git 目录重建仓库以清理历史','使用 zip 压缩后再提交到 Git，解压时靠流水线解包'],answer:[1],explanation:'Git LFS 是官方推荐的大文件管理方式，Codeup 原生支持 Git LFS，通过指针文本替代真实大文件，clone/pull 时按需下载 LFS 对象，既保证版本可追溯又避免仓库体积膨胀；其余方式均会破坏历史、影响协作或无法从根本上解决 git 对象膨胀的问题。',ref:'help.aliyun.com/zh/codeup/user-guide/git-lfs/'},
  {id:'yx06',module:'云效DevOps平台',type:'multi',question:'关于阿里云云效 Codeup 的 Webhook 能力，以下哪些是官方支持的典型事件触发场景？',options:['代码 Push 事件（向指定分支推送提交时触发）','合并请求 MR/PR 事件（创建、更新、合并、关闭时触发）','Tag 标签创建与删除事件','用户打开仓库首页浏览时触发'],answer:[0,1,2],explanation:'A 正确，Push 事件是 Webhook 最常用触发源之一，可用于触发流水线构建或通知机器人；B 正确，MR/PR 的创建、更新、审批、合并、关闭事件可用于评审通知与自动化门禁；C 正确，Tag 创建删除事件常用于触发发布流水线；D 错误，页面浏览属于普通访问行为，不是 Webhook 事件，若要监控审计应走操作日志而非 Webhook。',ref:'help.aliyun.com/zh/codeup/user-guide/webhook/'},
  {id:'yx07',module:'云效DevOps平台',type:'multi',question:'关于阿里云云效 Flow 流水线中的阶段（Stage）与任务（Step/Job）概念，以下哪些说法是正确的？',options:['流水线由若干阶段顺序组成，默认阶段之间为串行执行','同一阶段内的任务可以配置为并行执行，以缩短整体构建时长','阶段之间可配置前置条件（分支过滤、手动审批、前置阶段状态等）决定是否执行','流水线的任务与阶段完全等价，两者只是命名不同'],answer:[0,1,2],explanation:'A 正确，Stage 是流水线顺序编排单元，默认按定义顺序串行；B 正确，同阶段内部可通过"并行任务"设置让多个构建/测试步骤并发执行，加快流水线速度；C 正确，阶段可挂触发器条件（分支/tag/MR 过滤）、手动审批节点以及依赖前序阶段结果；D 错误，阶段 Stage 是更大粒度的编排块，任务 Step/Job 是阶段内的原子执行单元，二者不等价。',ref:'help.aliyun.com/zh/yunxiao/user-guide/pipeline-overview/'},
  {id:'yx08',module:'云效DevOps平台',type:'judge',question:'在云效 Flow 流水线任务中开启缓存后，缓存内容既可以针对 Maven 的 .m2/repository 目录，也可以针对 Node.js 的 node_modules 目录，从而减少重复下载依赖的耗时。',options:['正确','错误'],answer:[0],explanation:'云效 Flow 的流水线缓存支持自定义缓存目录与键，Maven 构建常将 ~/.m2/repository 加入缓存以避免重复拉取中央仓库依赖，Node.js 工程则常缓存 node_modules 或 npm/yarn/pnpm 的 store 目录，两者均属官方推荐用法，可显著降低构建时间。',ref:'help.aliyun.com/zh/devops/user-guide/cache-acceleration/'},
  {id:'yx09',module:'云效DevOps平台',type:'single',question:'在云效 Flow 流水线中，如果需要构建一种官方镜像未预装的特殊编译环境（如特定版本 GCC + Python 交叉工具链），以下哪种做法最符合官方最佳实践？',options:['在每个任务第一步中用 apt-get/brew 临时安装所需依赖，每次构建都重新安装','把源码改写成纯 Java 代码以绕开 GCC 依赖','使用自定义构建镜像（将工具链预装入 Docker 镜像并托管到 ACR/镜像仓库），在流水线中指定该镜像作为构建环境','把编译工具链的二进制文件直接提交到 Git 仓库，随代码一起下发'],answer:[2],explanation:'自定义构建镜像可将依赖、工具链、全局配置预先打包，流水线直接拉取使用，避免每次 apt-get 造成的耗时和不稳定。A 每次重装卸慢且易受网络源波动影响；B 显然不现实且违背需求；D 将二进制入库会导致仓库膨胀，违反代码仓库只存源代码的原则。',ref:'help.aliyun.com/zh/yunxiao/user-guide/custom-image/'},
  {id:'yx10',module:'云效DevOps平台',type:'single',question:'关于云效 Flow 流水线中变量的管理，以下哪项最能准确描述"加密变量"相比"普通变量"的差异？',options:['加密变量仅用于数学计算，普通变量用于字符串拼接','加密变量值在控制台显示与日志输出时会被脱敏，适合存放 AK/SK、密码等密钥；普通变量明文可见','加密变量只能在手动审批节点使用，普通变量在构建任务中使用','加密变量会被自动上传到公网备份，普通变量不会'],answer:[1],explanation:'Flow 的加密变量（密钥变量）会在保存后以密文存储，查看页面与流水线日志中均不显示原值，仅在任务执行时解密注入到运行环境，是存放 AK/SK、Token、数据库密码等敏感信息的推荐方式；普通变量用于可控的一般配置，明文可见。',ref:'help.aliyun.com/zh/devops/user-guide/variables/'},
  {id:'yx11',module:'云效DevOps平台',type:'single',question:'云效 Flow 流水线中的"手动审批"节点，关于其主要作用，以下哪项描述最准确？',options:['只是用来让流水线变慢以示庄重，没有实际作用','在进入关键阶段（如生产部署、制品发布）前暂停执行，等待指定审批人确认后再继续，可作为发布门禁','手动审批节点只能由企业主账号单人审批，不能配置多人','手动审批一旦配置就无法跳过或回退'],answer:[1],explanation:'手动审批节点是 DevOps 发布门禁的核心机制，在测试到预发、预发到生产等关键拐点使用，可配置审批人列表、审批模式（任一/会签）、超时策略等，既满足合规审计又避免误发生产。',ref:'help.aliyun.com/zh/yunxiao/user-guide/approval/'},
  {id:'yx12',module:'云效DevOps平台',type:'multi',question:'云效 Flow 流水线支持多种代码源触发方式。以下哪些是官方正式支持的三大常见触发器？',options:['Push 触发器：代码向指定分支推送提交时自动触发流水线','Tag 触发器：创建与正则匹配的 Git 标签时触发，常用于正式版本发布','MR/PR 触发器：创建或更新合并请求时触发，常用于合并前质量门禁','点击仓库 README.md 文件自动触发'],answer:[0,1,2],explanation:'A 正确，Push 触发器是日常开发中最广泛的触发方式，可做 CI 构建与单测；B 正确，Tag 触发常用于语义化版本发布流程，例如打 v1.2.3 标签后自动构建并上传制品；C 正确，MR/PR 触发器在开发者发起合并请求时触发，可绑定 Codeup 门禁，防止坏代码合入主干；D 错误，README 点击仅是浏览行为，不会触发流水线执行。',ref:'help.aliyun.com/zh/devops/user-guide/triggers/'},
  {id:'yx13',module:'云效DevOps平台',type:'multi',question:'在云效 Flow 中使用标准 Java Maven + Spring Boot 工程构建时，以下哪些步骤属于官方推荐的最佳实践组合？',options:['使用官方 Java/Maven 构建镜像或自定义镜像，确保 JDK 与 Maven 版本与项目一致','配置缓存目录指向本地 Maven 仓库路径（如 ~/.m2/repository）以加速依赖拉取','在构建任务中执行如 mvn clean package 的标准生命周期命令，并将目标 jar/war 上传至制品库或部署物','在构建步骤里本地手动启动 Spring Boot 应用监听 8080 端口长期运行'],answer:[0,1,2],explanation:'A 正确，一致的 JDK/Maven 版本避免构建环境差异；B 正确，Maven 依赖缓存是 Flow 推荐的加速手段之一；C 正确，mvn 生命周期打包并上传制品，是 Spring Boot 流水线的标准输出；D 错误，流水线构建任务属于短期执行，不应在构建容器中启动常驻进程，应用部署应放在独立的部署阶段或 K8s 部署任务中。',ref:'help.aliyun.com/zh/devops/user-guide/java-spring-boot/'},
  {id:'yx14',module:'云效DevOps平台',type:'multi',question:'在云效 Flow 中执行 Node.js npm 项目构建，以下哪些是常见且正确的步骤？',options:['选择合适的 Node.js 版本镜像（官方 Node 镜像或自定义镜像），与项目 .nvmrc/package.json engines 对齐','执行 npm ci 或 npm install 安装依赖，并建议缓存 node_modules 或 npm store','执行 npm run build / npm test 完成构建与单测，并将构建产物（如 dist 目录）上传为部署物或制品','把 node_modules 目录打包进 Git 仓库，流水线不再执行 npm install 以加速'],answer:[0,1,2],explanation:'A 正确，Node 版本差异会导致构建结果不一致，建议锁定；B 正确，npm ci 配合 lockfile 更稳定，缓存可减少重复安装；C 正确，构建与测试应在同一任务或同阶段内完成并上传产物；D 错误，node_modules 不应提交到 Git，体积庞大且易造成跨平台二进制兼容问题，应通过依赖管理器在构建期安装。',ref:'help.aliyun.com/zh/yunxiao/user-guide/nodejs-npm/'},
  {id:'yx15',module:'云效DevOps平台',type:'multi',question:'阿里云云效 Packages（制品仓库）原生支持以下哪几类制品仓库类型？',options:['Maven（Java/Gradle 制品）','NPM（Node.js 包）','PyPI（Python 包）','Generic（通用二进制/任意文件）'],answer:[0,1,2,3],explanation:'A 正确，Maven 仓库支持 pom、jar、war、sources 等标准发布；B 正确，NPM 仓库可做私有 npm Registry，配合 npm/pnpm/yarn 使用；C 正确，PyPI 仓库可托管私有 Python 包与依赖；D 正确，Generic 通用仓库可存放任意压缩包、二进制、安装包，适合非标准制品。四类均为 Packages 官方原生支持的核心仓库类型。',ref:'help.aliyun.com/zh/packages/user-guide/repository-types/'},
  {id:'yx16',module:'云效DevOps平台',type:'single',question:'关于阿里云云效 Packages 的"版本不可变"策略，以下哪项描述最准确？',options:['发布到仓库的制品版本一旦被下载，就会在 24 小时后自动删除','开启版本不可变后，同一版本号（如 mypkg-1.0.0）的制品不允许被覆盖或重复发布，防止构建结果漂移','版本不可变仅作用于包名，版本号可以任意重复覆盖','版本不可变策略需要额外付费购买数据库才能启用'],answer:[1],explanation:'版本不可变（Immutable Version）是制品管理的核心最佳实践，开启后相同版本号无法被再次覆盖写入，可避免"同版本号内容不同"带来的构建不可复现、线上问题难排查等问题，是可追溯、可审计发布流程的基础。',ref:'help.aliyun.com/zh/packages/user-guide/immutable-versions/'},
  {id:'yx17',module:'云效DevOps平台',type:'multi',question:'阿里云云效 Packages 的权限体系分为项目级与仓库级。以下关于两类权限的说法，哪些是正确的？',options:['项目级权限在项目范围内生效，可授予成员查看/推送/管理所有仓库的能力','仓库级权限仅对指定仓库生效，可精细化控制某个仓库谁能拉取、谁能推送、谁可管理','项目级权限与仓库级权限互斥，同一人不能同时拥有两者','管理员可针对临时发布场景为个别成员配置细粒度仓库级权限，而不必提升其整个项目权限'],answer:[0,1,3],explanation:'A 正确，项目级权限面向项目整体批量管理，适合团队负责人或核心成员；B 正确，仓库级权限更精细化，适合按服务或业务拆分读写责任；C 错误，项目级与仓库级权限可以叠加，取并集生效而非互斥；D 正确，精细赋权是官方推荐的最小权限实践，避免过度授予项目级权限带来的误改风险。',ref:'help.aliyun.com/zh/packages/user-guide/permissions/'},
  {id:'yx18',module:'云效DevOps平台',type:'judge',question:'阿里云云效 Packages 可以对上传的制品执行漏洞扫描、许可证合规检查以及恶意文件检测，并将风险结果展示在控制台，帮助团队在发布前识别问题。',options:['正确','错误'],answer:[0],explanation:'Packages 制品安全扫描能力覆盖 Maven/NPM/PyPI/Generic 等主流类型，可识别已知 CVE 漏洞、许可证合规风险（如 GPL/AGPL 传染性许可）以及恶意文件/可疑脚本特征，是 DevOps 链路中"左移安全"（Shift-left Security）的重要一环。',ref:'help.aliyun.com/zh/packages/user-guide/security-scanning/'},
  {id:'yx19',module:'云效DevOps平台',type:'single',question:'关于 Packages 制品与云效 Flow 流水线的对接，以下哪种做法最符合官方推荐？',options:['流水线构建结束后将制品通过 U 盘人工拷贝到制品库','在 Flow 构建任务成功后，使用官方提供的"上传到 Packages"步骤或相应 Maven/npm/pip/twine deploy 命令，将制品直接上传至对应 Packages 仓库','每次构建后本地手工登录控制台手动上传制品文件','将制品改名后直接上传到个人 OSS Bucket，不在 Packages 中登记'],answer:[1],explanation:'Flow 与 Packages 深度集成，既可通过可视化的"上传到 Packages"步骤一键上传，也可利用 Maven deploy/npm publish/twine upload 等原生客户端结合仓库凭证自动上传，保证构建、上传、版本号、审计信息自动关联，是标准 CI/CD 的最佳实践。',ref:'help.aliyun.com/zh/packages/user-guide/integrate-with-flow/'},
  {id:'yx20',module:'云效DevOps平台',type:'single',question:'效能洞察（DevOps Insight）中的 DORA 四指标之一"交付吞吐率（Deployment Frequency）"主要用于衡量以下哪项？',options:['团队每日编写的代码行数','团队将变更成功部署到生产环境的频率，反映持续交付能力','团队平均每人产出的需求个数','团队上线后服务器 CPU 使用率'],answer:[1],explanation:'交付吞吐率 Deployment Frequency 是 DORA 四大关键指标之一，统计单位时间内成功向生产环境部署的次数，次数越高通常代表团队 CI/CD 链路越成熟、交付批次越小、风险越可控。其余三项均不属于 DORA 指标范畴。',ref:'help.aliyun.com/zh/yunxiao/product-overview/dora-metrics'},
  {id:'yx21',module:'云效DevOps平台',type:'single',question:'DORA 四指标中的"交付时长（Lead Time for Changes，变更前置期）"指的是从代码提交到生产成功部署的耗时。若某团队该指标从 10 天缩短到 4 小时，以下哪项最可能是主要贡献因素？',options:['上线前额外增加 7 天的人工复核时间','引入云效 Flow 自动化流水线 + Codeup MR 质量门禁，减少手工打包、传输、审批环节','将所有服务器改为手动部署以降低自动化风险','每个需求都要求至少经过 3 轮跨部门纸质评审'],answer:[1],explanation:'交付时长反映的是研发交付链路的端到端效率，自动化流水线可显著缩短构建、测试、部署与审批流转时间，配合 MR 门禁将错误前置拦截、避免返工，是降低 Lead Time 的核心手段。其余选项都会显著拉长而非缩短交付链路。',ref:'help.aliyun.com/zh/devops-insight/user-guide/lead-time/'},
  {id:'yx22',module:'云效DevOps平台',type:'multi',question:'关于 DORA 四指标中的"变更失败率（Change Failure Rate）"与"服务恢复时间（Time to Restore Service / MTTR）"，以下说法正确的有哪些？',options:['变更失败率用于衡量有多少比例的生产部署最终导致了线上故障或服务降级，值越低代表质量越稳定','服务恢复时间（MTTR）衡量生产故障发生后到服务恢复正常所需的平均时长，值越短代表应急与回滚能力越强','降低变更失败率的常见手段包括 Codeup 主干保护、MR 评审、Flow 自动化测试与灰度发布、Packages 制品扫描','一旦变更失败率下降，服务恢复时间必然自动缩短，两者成完全线性反比关系'],answer:[0,1,2],explanation:'A 正确，变更失败率 CFR 是 DORA 的质量维度核心指标，低失败率代表交付质量稳定；B 正确，MTTR 反映研发与运维的故障响应能力，配合自动化回滚、灰度、可观测告警等能力能显著缩短；C 正确，上述手段均为将质量左移与快速止血的组合拳；D 错误，失败率低不代表恢复时间自动变短，两者虽相关但并非严格线性反比，团队仍需建设快速定位、快速回滚、自动化演练机制才能同时降低两项指标。',ref:'help.aliyun.com/zh/devops-insight/user-guide/dora-four-metrics/'},

  // ========== 2. 容器服务ACK ack01~26（12 单 + 11 多 + 3 判） ==========
  {id:'ack01',module:'容器服务ACK',type:'single',question:'关于阿里云 ACK 托管版（Managed Kubernetes）与专有版（Dedicated Kubernetes）在控制面归属和费用上的差异，以下哪种说法是正确的？',options:['托管版控制面 Master 节点由用户在自己账号下的 ECS 上创建并全额付费','专有版控制面由阿里云免费托管在阿里云基础设施账号中，用户不可见也无需付费','托管版控制面由阿里云托管（按集群/实例规格收费或免费额度），用户无需自行维护 Master ECS；专有版 Master 节点运行在用户账号 ECS 上，用户承担其 ECS 费用及运维责任','两者控制面节点都归属阿里云账号，用户均不需要任何控制面费用'],answer:[2],explanation:'ACK 托管版（Managed）将 etcd/apiserver/scheduler/controller-manager 托管在阿里云侧，按规格计费或有免费额度；专有版（Dedicated）控制面 Master 节点创建在用户 VPC 内的 ECS 上，归属用户账号并计费，用户需自行承担升级、备份、容量规划等运维责任，两者在归属与成本模型上有本质差异。',ref:'help.aliyun.com/zh/ack/product-overview/ack-overview'},
  {id:'ack02',module:'容器服务ACK',type:'multi',question:'阿里云 ACK 提供多种集群形态。以下关于专有版（Dedicated）、托管版（Managed）、ASK 无服务器版、边缘集群的描述，哪些是正确的？',options:['Managed 托管版：用户只需创建和管理 Worker 节点/节点池，控制面由阿里云托管升级，是大多数生产场景的首选','Dedicated 专有版：Master 与 Worker 均部署在用户 VPC，用户拥有最高控制权，适合对控制面自定义要求高或合规需要完全自管的场景','ASK 无服务器版：无需购买任何 Worker ECS，Pod 以弹性容器实例 ECI 方式按秒计费，适合突发流量、批量作业、CI 构建等峰谷明显场景','边缘集群：针对边缘节点（ENS/自建 IDC/现场设备）提供统一管控，支持云端下发应用到边缘节点并与云端控制面通信'],answer:[0,1,2,3],explanation:'A 正确，托管版屏蔽 Master 运维是 ACK 最主流形态；B 正确，专有版全部节点在用户侧，控制权最高；C 正确，ASK 基于 ECI 免节点管理、按量付费，弹性与成本优势显著；D 正确，边缘集群（ACK Edge）针对异构边缘节点统一纳管、云边协同，属于 ACK 的官方集群形态。四项均为官方产品定义中的典型差异点。',ref:'help.aliyun.com/zh/ack/product-overview/cluster-type-comparison'},
  {id:'ack03',module:'容器服务ACK',type:'single',question:'在 ACK 托管版集群中，当业务负载出现周期性高峰（例如每天 10-12 点 CPU 排队导致 Pod 大量 Pending），希望集群自动根据待调度 Pod 数量新增或释放节点，应启用以下哪个组件？',options:['Vertical Pod Autoscaler（VPA）','Horizontal Pod Autoscaler（HPA）','Cluster Autoscaler（CA，节点池自动伸缩）','CronHPA'],answer:[2],explanation:'Cluster Autoscaler（CA）是节点池级别的自动伸缩组件，持续扫描 Pending 无法调度的 Pod 并按节点池最小/最大节点数自动扩容或缩容 ECS 节点，解决的是"节点不够用"维度。HPA/VPA 针对 Pod 副本或资源请求调整，不会新增节点；CronHPA 是按时间调副本数，也不会新增节点。',ref:'help.aliyun.com/zh/ack/kubernetes/user-guide/cluster-autoscaler-overview'},
  {id:'ack04',module:'容器服务ACK',type:'multi',question:'关于 Kubernetes 污点 Taint 与容忍 Tolerations 在 ACK 节点池中的典型用法，以下哪些说法是正确的？',options:['节点打上 Taint 后，任何未携带对应 Toleration 的 Pod 默认不会被调度到该节点，同时也会被驱离（当 effect=NoExecute 时）','常用于将特殊节点（如 GPU 高算力机、大数据机型、专用安全池）与普通工作负载隔离，避免普通 Pod 占用昂贵资源','Tolerations 必须与 Taint 的 key、value、effect 三者严格完全相等，不支持 Equal 或 Exists 匹配方式','ACK 可在节点池级别批量设置默认 Taint，新建节点自动继承，也可在 Pod spec.tolerations 中声明容忍'],answer:[0,1,3],explanation:'A 正确，Taint 的三种 effect（NoSchedule/PreferNoSchedule/NoExecute）对应拒绝调度、倾向不调度、不调度并驱逐已有 Pod 的语义；B 正确，是 Taint/Toleration 的最典型业务落地场景；C 错误，容忍支持 operator: Exists（只要 key 存在即容忍，不校验 value）与 Equal（key+value+effect 精确匹配）两种，并非必须三者全等；D 正确，ACK 节点池原生支持在创建或修改时配置 Taint，节点自动继承。',ref:'help.aliyun.com/zh/ack/kubernetes/user-guide/taints-and-tolerations'},
  {id:'ack05',module:'容器服务ACK',type:'single',question:'阿里云 ACK 集群中，以下哪种网络插件支持 Pod 直接使用弹性网卡 ENI、Pod IP 与 VPC 处于同一扁平网络平面、可被 VPC 内其他服务直接三层路由？',options:['Flannel','Terway（ENI 多 IP 模式）','Calico BGP','Kube-router'],answer:[1],explanation:'Terway 是阿里云自研 CNI，在 ENI 多 IP / ENI 直通模式下 Pod 直接挂载弹性网卡辅助 IP，Pod IP 属于 VPC CIDR，可被 VPC 三层路由。Flannel 走 VxLAN Overlay，Pod IP 为虚拟 CIDR，默认不能被 VPC 对等三层互通。C/D 不是阿里云 ACK 默认官方提供的网络插件。',ref:'help.aliyun.com/zh/ack/product-overview/terway-overview'},
  {id:'ack06',module:'容器服务ACK',type:'single',question:'ACK 集群需要对一个节点进行硬件/内核升级维护，希望先禁止新 Pod 调度到该节点，再温和地将已有 Pod 迁移到其他节点（遵循 PodDisruptionBudget，保证服务可用性），应依次执行哪两个 kubectl 操作？',options:['先 kubectl uncordon，再 kubectl delete node','先 kubectl cordon，再 kubectl drain（带适当的 --ignore-daemonsets、--delete-emptydir-data 等参数）','先 kubectl taint 打上 NoSchedule，再直接 rm -rf /var/lib/kubelet 强拆节点','先 kubectl scale deployment 到 0，再 kubectl reboot node'],answer:[1],explanation:'cordon（警戒/拉闸）会将节点标记为 SchedulingDisabled，新 Pod 不再被调度上来；drain（排水）会优雅地驱逐节点上的 Pod（按 PDB 控制速率、等待优雅终止），是官方推荐的滚动维护操作范式。uncordon 是 cordon 的反向操作，与目标相反；直接删节点或删目录会造成服务中断，违反 SLO 维护最佳实践。',ref:'help.aliyun.com/zh/ack/kubernetes/user-guide/safely-drain-a-node-to-maintain-it'},
  {id:'ack07',module:'容器服务ACK',type:'multi',question:'关于 Kubernetes 工作负载 Deployment 的滚动更新策略（strategy: RollingUpdate），以下哪些说法是正确的？',options:['maxSurge 表示滚动过程中可超出期望副本数的最大额外副本数或百分比，控制一次可新增多少新版 Pod','maxUnavailable 表示滚动过程中相对于期望副本数允许不可用的最大 Pod 数或百分比，控制一次可下线多少旧版 Pod','若同时设置 maxSurge=25%、maxUnavailable=25%、replicas=4，则滚动期内最小可用 Pod 数为 3、最大总 Pod 数为 5','Deployment 一旦设置 RollingUpdate 就无法再回滚到历史 Revision，只能继续向前发布'],answer:[0,1,2],explanation:'A 正确，maxSurge 控制滚动放量的上冲；B 正确，maxUnavailable 控制滚动期的允许降级幅度；C 正确，replicas=4 下 25% 各取整为 1，因此最多可用 4+1=5、最小可用 4-1=3；D 错误，Deployment 通过 ReplicaSet 保留 revision 历史，支持 kubectl rollout undo deployment/xxx --to-revision=N 回滚到任意历史版本，ACK 控制台也支持可视化回滚。',ref:'help.aliyun.com/zh/ack/kubernetes/user-guide/rolling-update-of-a-deployment'},
  {id:'ack08',module:'容器服务ACK',type:'single',question:'需要部署一套有状态数据库集群（例如 MySQL 主从、ZooKeeper、Etcd），要求每个 Pod 拥有稳定的网络身份（如 pod-0.svc-headless.ns）、稳定的持久化存储（每个 Pod 独立 PVC，重建后仍挂载原卷），应优先使用以下哪种 Kubernetes 工作负载？',options:['Deployment','StatefulSet + Headless Service + volumeClaimTemplates','DaemonSet + EmptyDir','CronJob'],answer:[1],explanation:'StatefulSet 专门用于有状态应用：配合 Headless Service（clusterIP=None）为每个 Pod 生成稳定 DNS 身份 <ordinal>.<svc>.<ns>.svc.cluster.local；配合 volumeClaimTemplates 为每个 Pod 自动绑定独立 PVC，Pod 被删除重建后 ordinal 与 PVC 保持一致，数据与身份均稳定。Deployment 无稳定身份也不会为每个 Pod 生成独立 PVC；DaemonSet/CronJob 用途完全不符。',ref:'help.aliyun.com/zh/ack/kubernetes/user-guide/statefulset-overview'},
  {id:'ack09',module:'容器服务ACK',type:'multi',question:'关于 Kubernetes 的 DaemonSet、Job、CronJob 三类工作负载，以下哪些描述是正确的？',options:['DaemonSet：保证每个（或满足 nodeSelector/亲和性的）节点上恰好运行一个 Pod 副本，常用于日志采集、监控 Agent、CNI/存储插件等节点级守护进程','Job：用于一次性或并行批处理任务，Pod 运行到成功完成（exit 0）即结束，可通过 completions/parallelism 控制总成功次数与并发数','CronJob：基于 Cron 表达式周期性创建 Job，可设置 concurrencyPolicy、startingDeadlineSeconds、successfulJobsHistoryLimit 等策略','三者都会无限重启 Pod 以确保永远运行，不允许 Pod 退出成功（exit 0）后进入 Completed 状态'],answer:[0,1,2],explanation:'A 正确，DaemonSet 的"每节点一 Pod"语义使其成为节点侧守护进程的首选；B 正确，Job 是一次性批处理抽象，completions 控制总成功 Pod 数，parallelism 控制并发；C 正确，CronJob 在设定时刻创建一次性 Job 执行，常用于定时备份、报表、夜间批量等；D 错误，Job/CronJob 的 Pod 默认 restartPolicy=OnFailure/Never，成功退出后应进入 Completed/Succeeded，不会无限重启，无限重启保活是 Deployment/StatefulSet/DaemonSet 的 restartPolicy=Always 语义。',ref:'help.aliyun.com/zh/ack/kubernetes/user-guide/workload-overview'},
  {id:'ack10',module:'容器服务ACK',type:'judge',question:'在阿里云 ACK 中，Service 的类型 NodePort 会在每个节点上开放一个相同端口（默认范围 30000-32767），外部流量访问任意节点 IP:NodePort 都会由 kube-proxy 转发到后端 Endpoint Pod，因此节点宕机不影响通过该节点 NodePort 访问服务的可达性。',options:['正确','错误'],answer:[1],explanation:'NodePort 的确在所有节点上开放端口，kube-proxy 会将流量 DNAT 到健康的后端 Pod；但"访问宕机节点的 IP:NodePort"本身会因节点不可达导致 TCP 建连失败，并非完全无感，生产中通常需要在 NodePort 前方挂载 SLB/ALB（即 LoadBalancer 类型）并做健康检查，才能屏蔽单节点故障。题干后半句的"节点宕机不影响访问"是错误的。',ref:'help.aliyun.com/zh/ack/kubernetes/user-guide/service-overview'},
  {id:'ack11',module:'容器服务ACK',type:'multi',question:'关于 ACK 中 Service 的常见类型 ClusterIP、NodePort、LoadBalancer 以及 Ingress 的使用场景，以下哪些是正确的？',options:['ClusterIP：仅集群内部可达的默认 Service，适合服务间内部 RPC/HTTP 调用，不对外暴露','NodePort：通过节点 IP + 固定端口暴露，多用于联调或临时验证，生产上常配合外部负载均衡使用','LoadBalancer：自动申请并绑定阿里云 SLB/NLB，是对外暴露 TCP/UDP/HTTP 服务的推荐生产方式，可通过注解指定实例规格、计费、带宽等','Ingress：集群内七层路由入口，基于域名/路径将 HTTP/HTTPS 流量转发到不同后端 Service，背后由 Ingress Controller（如 Nginx Ingress、MSE Ingress）实现'],answer:[0,1,2,3],explanation:'A 正确，ClusterIP 是默认类型仅集群内可见；B 正确，NodePort 直接暴露节点端口但可用性依赖节点存活，多为辅助手段；C 正确，LoadBalancer 通过 Cloud Controller Manager 自动创建阿里云 CLB/NLB 并支持丰富注解，是四层公网入口首选；D 正确，Ingress 是七层路由抽象，ACK 提供 Nginx Ingress Controller 与 MSE Ingress 网关两种托管实现，支持按域名/路径分流、TLS 终止等。四项均符合官方最佳实践。',ref:'help.aliyun.com/zh/ack/kubernetes/user-guide/ingress-overview'},
  {id:'ack12',module:'容器服务ACK',type:'single',question:'ACK 中通过 LoadBalancer Service 对外暴露 TCP 服务，希望使用支持超高性能、百万级并发、支持跨 VPC/私网连接的新一代四层负载均衡，并通过注解指定，应选择以下哪种类型？',options:['Classic Load Balancer（CLB/经典型）','Network Load Balancer（NLB，通过 service.beta.kubernetes.io/alibaba-cloud-loadbalancer-address-type 及相关 NLB 注解）','应用型负载均衡 ALB（Ingress 场景）','ECS 直接绑定 EIP'],answer:[1],explanation:'阿里云 NLB（Network Load Balancer）是新一代四层高性能 LB，单实例可支撑超百万并发与超低时延，并支持跨 VPC 绑定后端、私网连接等高级能力，在 ACK 中通过注解 service.beta.kubernetes.io/alibaba-cloud-loadbalancer-spec: nlb.small、nlb.medium 等或新版 controller 参数即可创建 NLB 实例。CLB 是上一代四层；ALB 为七层（Ingress 使用），题干明确 TCP 四层高并发应选 NLB。',ref:'help.aliyun.com/zh/ack/kubernetes/user-guide/use-nlb-to-expose-services'},
  {id:'ack13',module:'容器服务ACK',type:'multi',question:'关于 ACK 的持久化存储：StorageClass、PV（PersistentVolume）、PVC（PersistentVolumeClaim）以及常见 CSI 驱动，以下哪些说法正确？',options:['StorageClass 定义存储的"等级模板"（如云盘性能级别、NAS 挂载点、OSS Bucket、回收策略等），PVC 指定 storageClassName 即可动态申请 PV，无需运维手工提前创建 PV','云盘 CSI 插件：对应阿里云 ESSD/PL0/PL1/PL2/PL3/Auto 云盘，典型 RWO（单节点读写）模式，适合数据库、单 Pod 挂载本地块存储场景','NAS CSI 插件：对应文件存储 NAS，支持 RWX（多节点共享读写），适合共享内容、日志共享、配置共享、CI 工作区等多 Pod 并发读写','OSS CSI 插件：对应对象存储 OSS Bucket，挂载后表现为 POSIX 文件系统，适合静态数据分发、图片/静态资源共享，不建议用于数据库高随机写场景'],answer:[0,1,2,3],explanation:'A 正确，动态制备（Dynamic Provisioning）+ StorageClass 是 ACK 推荐的主流用法；B 正确，云盘 CSI 将 ECS 云盘作为块设备挂载，天然单写入者 RWO，性能稳定适合数据库；C 正确，NAS 为分布式文件系统允许多 Pod 同挂载 RWX；D 正确，OSS CSI 基于 FUSE 语义映射对象存储，吞吐可但 IOPS/元数据延迟不佳，应避免用于 OLTP 数据库等强随机写负载。四项均为官方存储选型建议。',ref:'help.aliyun.com/zh/ack/product-overview/storage-overview'},
  {id:'ack14',module:'容器服务ACK',type:'single',question:'ACK 存储体系中，RWO（ReadWriteOnce）与 RWX（ReadWriteMany）是常见的访问模式。下列哪种 CSI 类型最匹配"多 Pod 跨节点同时读写同一份文件系统（如 WordPress 上传目录）"的诉求？',options:['云盘 CSI（ESSD）的 RWO','NAS CSI 的 RWX','OSS CSI 的静态挂载（只读）','EmptyDir'],answer:[1],explanation:'题干关键词是"多 Pod 跨节点同时读写"，对应 RWX；NAS CSI 基于阿里云文件存储，天然支持 NFS 多客户端同时挂载并并发读写，是该场景的标准选型。云盘 RWO 同一时刻只能被一个节点挂载；EmptyDir 生命周期与 Pod 绑定且不跨节点；OSS 读多写少且 POSIX 语义弱于 NAS，不适合作为通用共享上传目录。',ref:'help.aliyun.com/zh/ack/kubernetes/user-guide/nas-csi-overview'},
  {id:'ack15',module:'容器服务ACK',type:'multi',question:'关于 ACK 网络插件 Flannel（Overlay）与 Terway（ENI 多 IP / ENI-Trunking）的选型对比，以下哪些描述是正确的？',options:['Flannel 使用 VxLAN Overlay 封装，Pod CIDR 与 VPC 解耦，部署简单但 Pod 对外访问需经 SNAT，且 VPC 其他资源无法直接路由到 Pod IP','Terway ENI 多 IP 模式下 Pod IP 来自 VPC 交换机 CIDR，为 VPC 原生可达 IP，性能更优，且支持 Pod 级别安全组、带宽限制等云原生能力','Terway ENI-Trunking 相比传统 ENI 多 IP，可通过弹性网卡中继（Trunk ENI + Branch ENI）大幅提升单机可分配的 Pod/ENI 密度，适合高密度业务部署','Flannel 与 Terway 都支持为每个 Pod 绑定独立的 VPC 安全组并在 ECS 控制台查看'],answer:[0,1,2],explanation:'A 正确，Overlay 方案的核心特点就是虚拟 CIDR + 封装 + SNAT；B 正确，Terway 的核心卖点正是 VPC 原生 Pod IP + Pod 安全组；C 正确，ENI-Trunking 通过一条主 Trunk 网卡加大量 Branch ENI 突破 ECS 规格 ENI 数量限制，单机 Pod 密度显著提升；D 错误，Flannel Overlay 下 Pod 没有独立 VPC ENI，无法在 ECS 控制台按 Pod 绑定独立安全组，该能力是 Terway 独有。',ref:'help.aliyun.com/zh/ack/product-overview/select-a-cni-solution'},
  {id:'ack16',module:'容器服务ACK',type:'judge',question:'在 ACK Terway 模式下使用 Pod 安全组功能，可以为某个 Deployment 的所有 Pod 单独绑定与 ECS 节点不同的 VPC 安全组规则，从而对 Pod 出/入流量做精细化访问控制，该能力在 Flannel Overlay 模式下同样可用。',options:['正确','错误'],answer:[1],explanation:'Pod 安全组依赖 Pod 拥有独立的 VPC 弹性网卡（ENI）或辅助 IP 并能在 VPC 维度绑定 SG，该能力仅在 Terway ENI 模式下提供。Flannel Overlay 使用 VxLAN 虚拟 CIDR 封装，Pod 无独立 VPC 网卡，无法在 VPC 安全组层面按 Pod 粒度控制，因此题干中"Flannel 模式下同样可用"错误。',ref:'help.aliyun.com/zh/ack/kubernetes/user-guide/pod-security-group'},
  {id:'ack17',module:'容器服务ACK',type:'single',question:'关于 Helm 三大核心概念 Chart、Release、Repository 的关系，以下哪种描述最准确？',options:['Release 是打包好的 tarball，Chart 是一次安装运行实例，Repository 是本地缓存目录','Chart 是可复用的 Kubernetes 资源打包（含 templates + values.yaml），Release 是将某个 Chart 以指定 values 安装到集群产生的一次运行实例，Repository 是存放和分发 Chart 的仓库','三者都是存放 YAML 的本地文件夹，没有运行时概念','Helm 不支持 Release 的升级和回滚，必须每次重新 kubectl apply'],answer:[1],explanation:'Helm 的三要素为 Chart（可复用包=模板+默认值）、Release（安装到集群的某次具体实例，同名 release 同命名空间内唯一）、Repository（Chart 仓库如阿里云 ACR、官方 stable/bitnami 等）。A 选项三者关系写反；C 忽略运行时 Release 概念；D 违背 Helm upgrade/rollback 的核心能力，Helm 通过 revision 历史管理发布版本。',ref:'help.aliyun.com/zh/ack/kubernetes/user-guide/helm-overview'},
  {id:'ack18',module:'容器服务ACK',type:'multi',question:'关于 Helm Chart 的目录结构与 values.yaml 用法，以下哪些描述是正确的？',options:['标准 Chart 目录包含 Chart.yaml（元信息：name/version/appVersion 等）、values.yaml（默认参数）、templates/（被渲染的 Go template YAML）、charts/（子 Chart 依赖）等','values.yaml 中的键值可在模板中通过 .Values.xxx 引用，且可通过 helm install/upgrade -f values-prod.yaml 或 --set key=val 多次覆盖并合并','helm upgrade RELEASE CHART 用于滚动升级 Release 到新版 Chart 或新 values；helm rollback RELEASE REVISION 可回滚到指定历史 Revision（helm history 可查看）','helm repo add/update/remove/index 用于管理远端 Chart 仓库，但 Helm 不支持将自建 ACR 作为 Chart 仓库使用'],answer:[0,1,2],explanation:'A 正确，是 Helm Chart 的标准骨架；B 正确，values 优先级为：默认 values.yaml < 自定义 -f 文件 < --set/--set-string；C 正确，upgrade/rollback 配合 revision 是 Helm 发布管理的核心操作；D 错误，阿里云容器镜像服务 ACR 企业版/基础版均支持 Helm Chart 仓库（OCI 或 Helm Classic），可用 helm registry login 或 helm repo add 对接，是官方推荐的私有化 Chart 分发方式。',ref:'help.aliyun.com/zh/ack/kubernetes/user-guide/use-helm-to-deploy-applications'},
  {id:'ack19',module:'容器服务ACK',type:'single',question:'为 ACK 集群中的两个项目团队（prod/test）做资源与权限隔离：希望 test 命名空间最多只能使用 32 核 CPU / 64Gi 内存、每个容器默认 request 100m/128Mi，且 test 用户只能操作该命名空间下的 Pod/Deployment/Configmap。应依次选择以下哪组 Kubernetes 资源组合？',options:['仅 Namespace + StorageClass','Namespace + ResourceQuota + LimitRange + RBAC（Role/RoleBinding + ServiceAccount/User）','仅 ClusterRole + ClusterRoleBinding','Namespace + HPA + CA'],answer:[1],explanation:'Namespace 提供逻辑隔离边界；ResourceQuota 限制该命名空间的聚合资源上限（CPU/内存/存储/Pod 数等）；LimitRange 为命名空间设置默认/最小/最大 request&limit，防止容器忘记配置或超阈值；RBAC 中 Role/RoleBinding 是命名空间级权限，可对 test 用户或 ServiceAccount 只授予 Pod/Deployment/Configmap 等资源的 verb 权限。ClusterRole/RoleBinding 是集群级，不满足命名空间级细粒度。',ref:'help.aliyun.com/zh/ack/kubernetes/user-guide/multi-tenant-management-overview'},
  {id:'ack20',module:'容器服务ACK',type:'multi',question:'关于 ACK 中常见 Pod 故障状态及其排查思路，以下哪些匹配是正确的？',options:['ImagePullBackOff / ErrImagePull：几乎都是镜像拉取失败，优先检查镜像地址/tag 是否存在、私有镜像仓库的 imagePullSecret 是否正确配置、节点到仓库的网络/VPC 端点/安全组是否放通','CrashLoopBackOff：容器启动后反复退出并被 kubelet 重启，优先查看 kubectl logs（含 --previous 看崩溃前最后一次日志）与 describe 的 LastState 退出码，常见于配置错误、Probe 误判、入口进程异常','Pending：Pod 一直无法被调度到任何节点，常见原因包括资源不足（CPU/Mem/GPU）、节点选择器 nodeSelector/亲和性无匹配节点、PVC 无法绑定、Taint 无可容忍、CA 未启用或扩容失败','Pod 状态为 Running 但业务不就绪：无需关心 Probe，直接 kubectl delete pod 让其重建即可恢复一切问题'],answer:[0,1,2],explanation:'A 正确，ImagePullBackOff 常见排查路径如上；B 正确，CrashLoopBackOff 的第一手信息是容器日志+退出码+LastTerminationState；C 正确，Pending 的本质是调度失败（scheduler 无法打分或被 predicate 过滤），列出的四类为 ACK 日常最常见原因；D 错误，Running 但业务不就绪通常与 readinessProbe 未通过（endpoint 未加入 Service）、启动探针 startupProbe 超时、配置注入/依赖未就绪有关，盲目 delete pod 无法定位根因，正确做法是 kubectl describe 查看 Events 与 Probe 失败详情。',ref:'help.aliyun.com/zh/ack/best-practices/troubleshooting-pod-failures'},
  {id:'ack21',module:'容器服务ACK',type:'single',question:'某应用启动极慢（冷启动需约 90 秒加载模型），配置了 livenessProbe（initialDelaySeconds=30, periodSeconds=10）后 Pod 频繁被 kubelet 杀掉重启、一直无法对外提供服务。以下哪种修复方案最符合 Kubernetes 探针最佳实践？',options:['把 livenessProbe 的 initialDelaySeconds 改为 5 秒，让它尽早探活','移除所有 Probe，依赖容器进程不崩溃即可','新增 startupProbe（failureThreshold×periodSeconds 覆盖 90 秒以上启动窗口），在 startupProbe 成功前屏蔽 liveness/readiness；待应用启动完成后再由 liveness/readiness 接管存活与就绪','把 livenessProbe 和 readinessProbe 合并成一个 exec 调用 exit 0'],answer:[2],explanation:'Kubernetes 1.18+ 引入 startupProbe 专门解决慢启动应用被 liveness 误杀的问题：startupProbe 在应用启动阶段持续探测，一旦成功就将控制权交接给 liveness/readiness，失败次数×间隔需覆盖最长启动时间。A 会加剧误杀；B 丢失探活能力；D 混淆"存活"与"就绪"语义，readiness 应校验业务端口/健康路由真正可用，liveness 校验进程是否死锁。',ref:'help.aliyun.com/zh/ack/kubernetes/user-guide/configure-liveness-readiness-startup-probes'},
  {id:'ack22',module:'容器服务ACK',type:'multi',question:'关于 ACK Ingress 的常见配置：Nginx Ingress 与 MSE Ingress 网关、以及 CLB/NLB 入口注解，以下哪些描述是正确的？',options:['Nginx Ingress Controller 是 ACK 默认的开源七层入口控制器，支持 annotations 配置灰度分流、限流、跨域、重写、证书、白名单等大量 Nginx 能力','MSE Ingress（微服务引擎云原生网关）提供托管式、企业级七层入口，集成 WAF、JWT/OIDC、认证鉴权、标签路由、全链路灰度等高级治理能力，适合微服务与生产级入口','Ingress 资源可通过注解指定其前端 SLB/NLB 类型、带宽、计费方式、证书 ID、HTTPS 强制跳转等','Ingress 只能暴露 HTTP/HTTPS 七层服务，无法用于非 HTTP 的 TCP/UDP 入口暴露，后者应使用 LoadBalancer Service 或 NodePort'],answer:[0,1,2,3],explanation:'A 正确，Nginx Ingress 官方注解上百条，是通用入口首选；B 正确，MSE Ingress 是托管入口网关，相比自建 Nginx 集成更多治理与安全能力，减少自维成本；C 正确，ACK 提供大量 service.beta.kubernetes.io/alibaba-cloud-loadbalancer-* 与 ingress 相关注解控制入口实例属性；D 正确，Ingress API 语义面向 HTTP/HTTPS 路由，TCP/UDP 端口暴露的正确位置是 Service 的 NodePort/LoadBalancer 类型，Nginx Ingress 虽可用 ConfigMap 代理 TCP/UDP 但并非 Ingress API 标准做法。',ref:'help.aliyun.com/zh/ack/kubernetes/user-guide/mse-ingress-overview'},
  {id:'ack23',module:'容器服务ACK',type:'single',question:'ACK 自定义节点镜像的典型价值与使用方式，以下哪种描述最准确？',options:['自定义节点镜像用于替换 kubelet/containerd 二进制，让集群使用完全不同的容器运行时','可基于阿里云 CentOS/Alibaba Cloud Linux 自定义镜像预装驱动（GPU/RDMA/异构加速）、安全基线、安全 Agent、企业 RPM 包等，创建节点池时指定该镜像 ID，新节点启动后无需再跑大量初始化脚本，缩短扩容时长并提升一致性','自定义节点镜像只能用于 ASK 无服务器集群，托管版集群不能使用','自定义节点镜像必须大于 200GiB，否则无法被 ACK 识别'],answer:[1],explanation:'ACK 托管版/专有版的节点池均支持指定 ECS 自定义镜像 ID，通过预先封装 GPU 驱动、安全基线、合规组件、字体/内核参数等，避免节点扩容时 user-data 安装脚本长耗时、失败率高的问题，是 AI/HPC、金融安全合规场景的常用优化手段。A 做法会破坏 K8s 兼容矩阵，官方不建议；C 与事实相反，ASK 无需用户节点镜像；D 无此要求，通常 40~120GiB 系统盘即可。',ref:'help.aliyun.com/zh/ack/kubernetes/user-guide/use-custom-images-to-create-nodes'},
  {id:'ack24',module:'容器服务ACK',type:'judge',question:'在 ACK 中执行 helm upgrade 发布新版本 Chart 时，若新 values 中镜像 tag 写错导致镜像拉不到，Release Revision 不会增加，集群中当前运行的 Release 也不会有任何 Pod 变更，因此 Helm 是事务性的、要么全成功要么全不生效。',options:['正确','错误'],answer:[1],explanation:'helm upgrade 执行时，会先生成并提交新的 Manifest 给 API Server 并自增 Revision，随后由 Kubernetes 控制器异步滚动执行 Deployment/StatefulSet 等对象，并非数据库式事务。若镜像 tag 错误，Revision 已经加一，Kubernetes 侧会出现 ImagePullBackOff 的新 Pod，旧版本是否保留取决于 maxUnavailable/maxSurge，需要通过 helm rollback 回到上一 Revision 才能恢复，因此"Revision 不会增加、全不生效"的断言错误。',ref:'help.aliyun.com/zh/ack/kubernetes/user-guide/helm-use-best-practices'},
  {id:'ack25',module:'容器服务ACK',type:'multi',question:'关于 Kubernetes RBAC（Role-Based Access Control）在 ACK 多租户场景中的典型用法，以下哪些说法是正确的？',options:['ServiceAccount 是 Pod 内部访问 API Server 的身份载体，通常配合 Volume 挂载的 token 使用；User/Group 通常对接 RAM 子账号/RAM 角色（通过 ACK RAM RBAC 映射）','Role + RoleBinding 是命名空间级授权：Role 定义资源+动作（verbs）白名单，RoleBinding 将 Role 绑定到 Subject（User/Group/ServiceAccount），仅在单个命名空间生效','ClusterRole + ClusterRoleBinding 是集群级授权：可授予所有命名空间资源或节点、PV、StorageClass 等集群范围资源的权限，适合集群管理员、CSI/CNI 组件 ServiceAccount','若希望某用户在所有命名空间都能查看 Pod，应创建 Role 并在每个命名空间单独 RoleBinding，没有任何集群级抽象能一次性授予跨命名空间权限'],answer:[0,1,2],explanation:'A 正确，SA 是工作负载侧身份，外部身份（RAM/RBAC）走 User/Group 映射；B 正确，Role/RoleBinding 的作用域严格限制在创建时的命名空间；C 正确，ClusterRole/ClusterRoleBinding 负责集群资源与跨命名空间资源授权；D 错误，"所有命名空间查看 Pod"正是 ClusterRole（资源 pods、verbs list/get/watch）+ ClusterRoleBinding 的典型用例，无需逐命名空间重复创建 Role/RoleBinding。',ref:'help.aliyun.com/zh/ack/kubernetes/user-guide/rbac-overview'},
  {id:'ack26',module:'容器服务ACK',type:'single',question:'关于 ACK Service 的会话亲和性（Session Affinity），希望在同一客户端 IP 的生命周期内将其请求始终转发到同一个后端 Pod（例如保留登录态缓存于 Pod 内存中），应使用以下哪种配置？',options:['Service.spec.externalTrafficPolicy=Local','Service.spec.sessionAffinity=ClusterIP（默认）','Service.spec.sessionAffinity=ClientIP，并可配置 sessionAffinityConfig.clientIP.timeoutSeconds（默认 10800 秒）','为 Service 设置注解 type=Headless'],answer:[2],explanation:'Kubernetes Service sessionAffinity=ClientIP 即按源 IP 哈希选择后端，同 Client IP 命中同 Pod，并可通过 timeoutSeconds 控制粘合过期时间，是传统"粘性会话"的标准实现。externalTrafficPolicy=Local 目的是保留客户端源 IP 并避免跨节点转发，并非会话粘；ClusterIP 是无亲和（轮询/随机）默认值；Headless Service 不做负载均衡，返回所有 Pod IP，由客户端自行选择。',ref:'help.aliyun.com/zh/ack/kubernetes/user-guide/service-session-affinity'},

  // ========== 3. 容器镜像ACR acr01~16（7 单 + 7 多 + 2 判） ==========
  {id:'acr01',module:'容器镜像ACR',type:'single',question:'阿里云容器镜像服务 ACR 提供多种实例类型，面向大型企业客户、需要多可用区容灾、跨地域同步、P2P 分发加速与企业级 SLA 承诺的场景，应选择以下哪一实例类型？',options:['默认实例（个人版，免费）','ACR 基础版','ACR 企业版（EE，含标准版/高级版/旗舰版）','OSS Bucket + Nginx 自建镜像仓库'],answer:[2],explanation:'ACR 企业版（EE）面向企业生产，支持多可用区部署、跨地域同步、P2P 加速、Helm Chart 仓库、安全扫描、企业级 SLA 等能力；默认实例仅个人免费使用，基础版功能低于 EE；自建方案非阿里云官方托管，不享受 ACR 能力矩阵。',ref:'help.aliyun.com/zh/acr/product-overview/container-registry-editions'},
  {id:'acr02',module:'容器镜像ACR',type:'multi',question:'关于 ACR 的"命名空间"和"镜像仓库（Repository）"的常见用法，以下哪些描述是正确的？',options:['命名空间是资源隔离单元，可设置为"公开"或"私有"；公开命名空间下的所有仓库均可被匿名拉取，私有需登录并具有 RAM 权限','Repository 名称需符合 DNS/URL 友好规则：小写字母、数字、分隔符（- _ . /）且不以分隔符开头或结尾，可使用多级路径（如 acme/order/api）表达业务分层','Tag 不可变（Immutable）规则开启后，相同 Tag 推送会被服务端拒绝，只能推送新 Tag，用于防止生产镜像被意外覆盖导致版本混乱','Tag 保留策略只能按"最近推送时间"保留最新 N 天，无法按数量保留最近 N 个 Tag'],answer:[0,1,2],explanation:'A 正确，命名空间公开/私有权限决定访问范围，是最常用的资源隔离粒度；B 正确，仓库名规则由 OCI Distribution Spec 与 ACR 控制台同时约束，多级路径是行业常见组织方式；C 正确，Tag 不可变是保障生产可追溯性的重要配置，可在命名空间/仓库级开启；D 错误，Tag 保留策略同时支持"按 Tag 数量保留最近 N 个"与"按天数保留 N 天内推送的 Tag"两类规则，二者可叠加使用。',ref:'help.aliyun.com/zh/acr/user-guide/manage-namespaces'},
  {id:'acr03',module:'容器镜像ACR',type:'single',question:'在 ACR 企业版中对镜像执行"安全扫描"后，会产出三类风险报告供用户评估与处置，以下哪一项不属于这三类官方风险分类？',options:['系统漏洞（按 CVE 编号分级：Critical/High/Medium/Low）','恶意文件（病毒、挖矿程序、后门、可疑二进制等）','许可证合规风险（开源组件许可证冲突，如 GPL 污染闭源产品）','应用性能瓶颈（基于 eBPF 自动采样出慢函数与热点 CPU 函数）'],answer:[3],explanation:'ACR 安全扫描的三大类风险即：系统漏洞 CVE、恶意文件、许可证合规。D 属于 APM/可观测领域的性能剖析，非镜像静态扫描能力。',ref:'help.aliyun.com/zh/acr/user-guide/security-scanning-overview'},
  {id:'acr04',module:'容器镜像ACR',type:'multi',question:'关于 ACR 企业版的镜像"同步"能力，以下哪些说法是正确的？',options:['支持跨地域同步：如华东1（杭州）EE 实例 同步到 华北2（北京）EE 实例，实现异地灾备与就近拉取','支持跨实例同步：源与目标均为 EE 实例，可在企业版控制台创建"同步实例/同步规则"，非 EE 的默认实例与基础版不在支持范围内','支持跨账号同步：通过 RAM 角色授权源账号读取目标实例，无需在目标侧共享 AK 明文','同步触发方式为"按小时定时扫描"，不支持 Tag push 事件驱动的实时同步'],answer:[0,1,2],explanation:'A 正确，跨地域同步是 EE 异地灾备的典型用法；B 正确，同步能力是 EE 专属，源目标均需为企业版实例；C 正确，跨账号依赖 RAM 角色 + 信任策略 + 权限策略完成授权，避免 AK 泄漏；D 错误，同步规则支持"Tag 推送触发"（Tag Push → 自动同步）与"自定义触发"（按规则/手动）两种，生产常用前者以实现准实时同步。',ref:'help.aliyun.com/zh/acr/user-guide/synchronize-images-between-instances'},
  {id:'acr05',module:'容器镜像ACR',type:'multi',question:'ACR 提供多种"触发器（Trigger）与协作能力"用于打通 CI/CD 与容器运行时，以下哪些描述是正确的？',options:['ACK 触发器：推送新镜像 Tag 后自动触发 ACK 集群中指定 Deployment/StatefulSet 的滚动更新，无需额外写 Jenkins Pipeline 调用 kubectl','Webhook 触发器：镜像推送/扫描完成等事件可通过 Webhook 回调 Jenkins、云效 Flow、自建 IM 机器人等系统，便于流水线门禁与通知','触发器规则可按仓库名、Tag 正则（如 ^v\d+\.\d+\.\d+$）限定触发范围，避免 latest 或开发分支误触发生产滚动','触发器仅支持 HTTP 回调，不支持对 ACK 集群 API Server 直接操作，必须通过公网暴露 Jenkins 才能生效'],answer:[0,1,2],explanation:'A 正确，ACK 触发器是 ACR 与 ACK 原生联动的快捷方式，内部通过授权调用集群 API Server 完成 patch image；B 正确，Webhook 支持多种事件类型，是对接第三方 CI/CD 的通用方式；C 正确，Tag 正则匹配是防止"发布污染"的关键机制，生产环境建议关闭 latest 触发；D 错误，ACK 触发器可直接操作托管集群（通过内网与服务身份鉴权），无需公网暴露 Jenkins，也无需用户自行提供 kubectl 接入点。',ref:'help.aliyun.com/zh/acr/user-guide/create-a-trigger'},
  {id:'acr06',module:'容器镜像ACR',type:'judge',question:'阿里云容器镜像服务 ACR 企业版（EE）支持跨地域实例间的镜像自动同步，并且可以配置触发规则（例如每次向主实例推送指定仓库镜像后自动同步到灾备实例）。',options:['正确','错误'],answer:[0],explanation:'ACR 企业版提供"同步实例"功能，支持在命名空间级别配置源/目标实例对，并可与仓库 Trigger 联动；支持跨地域、跨账号、跨实例同步，可用于异地灾备与就近拉取场景。',ref:'help.aliyun.com/zh/acr/user-guide/synchronize-images-between-instances/'},
  {id:'acr07',module:'容器镜像ACR',type:'single',question:'某企业希望在 ACR 命名空间级别避免"同一 Tag 被反复覆盖推送"导致生产镜像不可追溯、回滚困难的问题，应开启以下哪一功能？',options:['Tag 保留策略（保留最近 30 个 Tag）','Tag 不可变（Immutable Tag / Tag 锁定）','开启仓库的"匿名拉取"','将仓库改名为 latest 结尾以提醒团队'],answer:[1],explanation:'Tag 不可变规则开启后，对同一 Tag 的二次推送会被 ACR 服务端拒绝返回 409，只能通过新 Tag 发布新版本，是保证不可变基础设施与 GitOps 版本一致性的核心配置。保留策略只负责清理旧 Tag；匿名拉取是访问控制；改名无法从机制上阻止覆盖。',ref:'help.aliyun.com/zh/acr/user-guide/configure-immutable-tags'},
  {id:'acr08',module:'容器镜像ACR',type:'multi',question:'关于 ACR 安全扫描的触发方式与流水线门禁联动，以下哪些做法符合官方推荐？',options:['开启"推送自动扫描"：每次 docker push 完成后 ACR 自动触发扫描，无需人工排队点击','可在云效 Flow / Jenkins 流水线中"先构建推送 → 调用 ACR 扫描 API 等待结果 → 判断高危/Critical 数量阈值 → 超标则阻断发布并告警"','生产发布前建议将"扫描无 Critical 且 High 不超过 3 个"作为发布门禁条件，恶意文件、GPL 等高风险许可证也应阻断','ACR 扫描结果只在控制台可见，无法通过 OpenAPI/SDK 程序化读取，因此无法做门禁'],answer:[0,1,2],explanation:'A 正确，推送自动扫描是 EE 默认推荐的启用方式，保证每个新 Tag 都被覆盖；B 正确，这是 DevSecOps 的典型流水线结构——"构建→推送→扫描→门禁→部署"；C 正确，企业通常以漏洞严重等级数量、恶意文件有无、许可证合规性作为阻断条件，具体阈值按安全基线制定；D 错误，ACR 提供扫描结果查询 OpenAPI 与 SDK，可被 Flow/Jenkins/GitLab CI 等系统程序化消费。',ref:'help.aliyun.com/zh/acr/user-guide/automatically-scan-images-upon-push'},
  {id:'acr09',module:'容器镜像ACR',type:'single',question:'ACR 企业版旗舰版提供的"P2P 分发加速"能力，对以下哪一场景的价值最显著？',options:['单节点个人开发者 docker pull 自己的私有镜像','数千台 ECS/ACK 节点在短时间内并发拉取同一个 GB 级大镜像（如 AI 训练镜像、发布窗口批量扩容）','CI 构建机向 ACR push 大量分层镜像','Helm 仓库中保存数百个 Chart 文件'],answer:[1],explanation:'P2P 分发通过节点间互相共享已下载分片，极大降低对源仓库带宽与 QPS 的压力，解决"大镜像 + 高并发拉取"时的拉取慢、源站出口被打满的问题。A 节点数太少收益不明显；C 是推送非拉取；D Chart 文件体积通常很小，不是 P2P 核心场景。',ref:'help.aliyun.com/zh/acr/user-guide/p2p-acceleration-overview'},
  {id:'acr10',module:'容器镜像ACR',type:'multi',question:'关于 ACR "Tag 保留策略（Retention）"的作用与配置，以下哪些描述是正确的？',options:['可以按"Tag 数量"保留最近 N 个，超出部分自动清理，用于防止开发仓库 Tag 无限膨胀导致存储费用飙升','可以按"天数"保留最近 N 天内推送的 Tag，过期的旧 Tag 自动删除，适合按发布周期清理的场景','保留策略作用域可以细到命名空间或单个仓库，并可通过 Tag 正则排除如 ^release-.* 的重要生产 Tag 不被清理','保留策略会同时删除镜像对应的二进制层文件，即使该层被其他仓库的 Tag 共用引用也会被一并清除，无需担心引用计数'],answer:[0,1,2],explanation:'A/B 正确，分别对应数量型与时间型两种保留策略；C 正确，通过"包含/排除规则 + Tag 正则"避免误删生产关键 Tag 是官方推荐用法；D 错误，ACR 内部采用分层引用计数，只有某层不再被任何 Tag 引用时才会真正回收，保留策略删除的只是 Tag Manifest 元数据与不再被引用的层，不会误删共用层。',ref:'help.aliyun.com/zh/acr/user-guide/configure-retention-rules'},
  {id:'acr11',module:'容器镜像ACR',type:'single',question:'阿里云 ACR 企业版支持托管 Helm Chart 仓库（Chart 托管版），以下哪一项关于其使用方式的描述是正确的？',options:['Chart 只能以 OCI Artifacts 方式推送，不支持传统 helm repo index 的 HTTP(S) 拉取','与普通镜像仓库完全隔离，Chart 仓库必须新建独立的 EE 实例才能使用','可在命名空间内直接创建类型为"Chart"的仓库，支持 helm push / helm repo add 两种协议，并可在控制台查看 Chart 版本列表、依赖与 values.yaml','ACR Chart 仓库不支持设置 Tag/版本不可变与保留策略，只能手动删除 Chart'],answer:[2],explanation:'ACR Chart 仓库是 EE 命名空间内的特殊仓库类型，同时兼容 Helm Classic（HTTP index.yaml）与 OCI Artifacts 两种使用方式，可在控制台查看版本、依赖、values 并设置不可变与保留策略。A 说"只支持 OCI"错误；B 无需新建实例；D 与事实相反，均支持不可变和保留策略。',ref:'help.aliyun.com/zh/acr/user-guide/helm-chart-repository-overview'},
  {id:'acr12',module:'容器镜像ACR',type:'single',question:'关于 ACR 的"OCI Artifacts"能力（支持存储 OCI 规范下的非镜像制品），以下哪一项不属于其典型可托管对象？',options:['镜像漏洞扫描结果的签名证明与 SBOM（软件物料清单）制品','Helm 3 Chart（OCI 协议）、Cosign 签名、OPA/Sigstore Policy Bundle','以 OCI 格式封装的 WASM 模块、数据集、ML 模型','ACK 集群 etcd 实时 WAL 日志流'],answer:[3],explanation:'OCI Artifacts 将仓库从"仅存镜像"扩展为"存任意 OCI 制品"，A/B/C 三类均为社区与 ACR 支持的典型场景。D etcd WAL 是持续追加写入的状态机日志，不适合以 OCI Manifest + Layer Blob 这种一次写入不可变的对象形态存储。',ref:'help.aliyun.com/zh/acr/user-guide/oci-artifacts-overview'},
  {id:'acr13',module:'容器镜像ACR',type:'multi',question:'某团队希望 ACR 推送新镜像后能够自动"滚动更新 ACK 集群中的 Deployment"，并将结果通知到钉钉群。以下哪些方案组合可以实现？',options:['方案一：创建 ACR 触发器类型为"ACK 触发器"，选择目标集群/命名空间/Deployment 与容器名；同时创建 Webhook 触发器指向钉钉自定义机器人地址（或经云效 Flow 转码）','方案二：使用 ACR Webhook 回调 Jenkins，在 Jenkins Pipeline 中执行 kubectl set image 更新 Deployment 并调用钉钉发消息；但需保证 Jenkins 与 ACK 的 API Server 网络与鉴权打通','方案三：完全依赖 Kubernetes CronJob 每 5 分钟轮询 ACR V2 API 拉取最新摘要并与当前 Deployment 比较，若不同则 patch，天然支持事件驱动','方案四：开启 ACR Tag 不可变策略即可，它会自动通知 ACK 滚动更新，无需任何触发器配置'],answer:[0,1],explanation:'A 正确，ACK 触发器 + Webhook 是官方原生双通道实现；B 正确，这是自建 CI/CD 的经典落地方式，Jenkins 侧通过 kubeconfig/RAM Role for ServiceAccount 接入集群；C 错误，CronJob 轮询属"拉模型"并非事件驱动，且频繁轮询会产生额外流量与延迟；D 错误，Tag 不可变只限制推送覆盖，与 ACK 部署更新无直接联动关系。',ref:'help.aliyun.com/zh/acr/user-guide/create-a-trigger'},
  {id:'acr14',module:'容器镜像ACR',type:'multi',question:'关于 ACR 各版本能力对比（默认实例 / 基础版 / 企业版 EE 标准版-高级版-旗舰版），以下哪些表述是正确的？',options:['默认实例（个人免费版）适合个人开发者学习与小型项目，仅提供单地域、命名空间配额有限、安全扫描需单独付费或有限次，无跨地域同步与企业 SLA','基础版相比默认实例具备更高的命名空间/仓库配额与域名独立访问入口，提供部分安全扫描，但仍不支持跨地域同步、P2P 加速与多可用区容灾等企业能力','企业版 EE 标准版及以上支持多可用区部署、跨地域/跨实例/跨账号同步、企业 SLA、Helm Chart 仓库；高级版与旗舰版在此基础上增加更多安全能力、P2P 加速、更大 QPS 与带宽规格','四个版本都支持"Helm Chart 托管 + P2P 分发加速 + 跨地域同步"三项能力，仅价格与 QPS 上限不同'],answer:[0,1,2],explanation:'A 正确，默认实例的免费定位决定能力边界；B 正确，基础版为中小团队提供更稳定的个人/团队仓库，能力介于默认与 EE 之间；C 正确，EE 是企业生产级首选，各子版本间在安全与性能规格上分层；D 错误，Chart 托管、P2P 加速、跨地域同步均为 EE 专属能力，默认实例与基础版不提供，"四个版本都支持"显然错误。',ref:'help.aliyun.com/zh/acr/product-overview/container-registry-editions'},
  {id:'acr15',module:'容器镜像ACR',type:'single',question:'在跨账号镜像同步场景中（账号 A 的 ACR EE 作为源，账号 B 的 ACR EE 作为目标），官方推荐的授权方式是以下哪一种？',options:['把账号 A 的 AccessKey ID/Secret 明文写入账号 B 的同步规则中','在账号 B 中创建 RAM 角色，信任账号 A 的云账号 ID，并为该角色授予 ACR 写入等最小权限；账号 A 的同步规则通过"跨账号角色 ARN"方式调用','使用账号 B 的 root 账号登录账号 A 的控制台进行配置','直接把源仓库设为公开，让目标实例匿名拉取即可'],answer:[1],explanation:'ACR 跨账号同步的标准做法是"RAM 角色 + 信任策略 + 最小权限"：目标账号创建角色、信任源账号、授予 acr:PushImage 等写权限，源账号侧配置同步时指定该角色 ARN。A 明文 AK 有泄漏风险；C 违反最小权限与账号隔离原则；D 将私有代码资产对外公开属于严重安全风险。',ref:'help.aliyun.com/zh/acr/user-guide/synchronize-images-across-accounts'},
  {id:'acr16',module:'容器镜像ACR',type:'judge',question:'ACR 安全扫描的许可证合规风险检测，仅能识别 Dockerfile 中显式声明的 LICENSE 文件，无法识别镜像内各 OS 包与应用依赖（如 npm/pip/jar）所携带的开源许可证，因此对依赖供应链合规基本没有价值。',options:['正确','错误'],answer:[1],explanation:'ACR 企业版安全扫描除解析 LICENSE 文件外，还会通过 SBOM 与包管理器元数据识别镜像中 apk/dpkg/rpm、npm/pip/gem/maven 等常见依赖及对应许可证，并根据预设策略（如禁止 GPL/AGPL 感染闭源）发出合规风险，是供应链安全的重要一环。题干断言"无法识别依赖、基本无价值"与产品能力相反，故错误。',ref:'help.aliyun.com/zh/acr/user-guide/license-compliance-scanning'},

  // ========== 4. IaC与运维编排 iac01~22（10 单 + 10 多 + 2 判） ==========
  {id:'iac01',module:'IaC与运维编排',type:'single',question:'在阿里云 ROS 模板的顶层结构中，用于声明"创建资源所需的输入参数（如实例规格、镜像 ID、VPC 网段），并可在创建栈时由用户动态传入"的一级区块是以下哪一项？',options:['Mappings','Parameters','Outputs','Conditions'],answer:[1],explanation:'Parameters 是 ROS 模板的输入参数区，可通过 Type、Default、AllowedValues、ConstraintDescription 等字段定义类型、默认值和取值约束，用户在创建栈时可按控制台或 CLI 覆盖默认值；Mappings 用于静态键值查表，Outputs 用于对外返回栈属性，Conditions 用于条件创建资源，均与"动态输入参数"语义不同。',ref:'help.aliyun.com/zh/ros/developer-reference/parameters'},
  {id:'iac02',module:'IaC与运维编排',type:'single',question:'在 ROS 栈生命周期中，执行"更新栈"操作前若希望先精确预演本次变更会对哪些资源执行 Create/Update/Delete，而不会立即落盘修改，应使用以下哪种 ROS 能力？',options:['直接执行更新栈并开启回滚','创建变更集（Change Set）并查看变更类型后再执行','对栈执行"重建"操作','对每个资源单独在控制台手工修改'],answer:[1],explanation:'ROS 变更集（Change Set）是一种安全的"更新预演"机制：提交模板与参数差异后，ROS 会在后台计算出每个受影响资源的 Action（新增、修改、删除、重建），但不会真正执行，用户在控制台或 API 中逐项确认无误后，再选择"执行变更集"落地更新，是生产环境规避误改的最佳实践。',ref:'help.aliyun.com/zh/ros/user-guide/change-sets'},
  {id:'iac03',module:'IaC与运维编排',type:'multi',question:'关于 ROS 模板的顶层章节 Resources、Outputs、Mappings、Conditions 的作用，以下哪些说法是正确的？',options:['Resources：必填章节，用于声明模板要创建/管理的云资源（如 ECS/VPC/SLB/RDS）及其属性与依赖关系','Outputs：用于声明栈创建/更新完成后对外输出的值（如 SLB 公网 IP、RDS 连接串），可被嵌套栈父栈引用或通过控制台/API GetStackResource 读取','Mappings：用于定义静态键值映射表，模板可通过 Fn::FindInMap 根据 Key 查询，常用于"按地域返回不同镜像 ID/实例规格族"等场景','Conditions：用于定义布尔条件，Resources 和 Outputs 可通过 Condition 字段决定某资源/输出是否创建，常用于按需开通可选功能（如按参数决定是否创建 NAT 网关）'],answer:[0,1,2,3],explanation:'A 正确，Resources 是模板的核心必填章节，资源之间可用 DependsOn 或 Ref/Fn::GetAtt 隐式声明依赖；B 正确，Outputs 是栈与外部/嵌套父栈通信的主要通道；C 正确，Mappings 的典型场景是按 Region/AZ 选择镜像与规格族，避免模板参数过于庞大；D 正确，Conditions 通过 Fn::If/And/Or/Not 组合，配合 Resource/Output 上的 Condition 字段实现"条件资源/输出"。四项均为 ROS 模板的官方定义。',ref:'help.aliyun.com/zh/ros/developer-reference/template-structure'},
  {id:'iac04',module:'IaC与运维编排',type:'multi',question:'关于 ROS 嵌套栈（Nested Stack，使用资源类型 ALIYUN::ROS::Stack）的使用场景与优势，以下哪些说法是正确的？',options:['当模板过大（接近 ROS 单模板体积/资源数上限）或逻辑可按模块化拆分时，可将网络层、应用层、数据库层分别写成子模板并在父模板中以嵌套栈引用','嵌套栈支持通过 Outputs 将子栈的关键信息（如 VSwitchId、Endpoint）返回给父栈，父栈可用 Fn::GetAtt 读取并传递给其他子栈或资源','嵌套栈虽然可以复用模板，但子栈内的资源无法被父栈的回滚策略联动保护，必须单独回滚','嵌套栈天然支持对子模板做版本化（例如把不同版本子模板放入 OSS 并指定不同 URL），便于团队共享网络基线、ECS 基线等通用模板'],answer:[0,1,3],explanation:'A 正确，嵌套栈是模板模块化、规避模板上限的标准手段；B 正确，子栈 Outputs 可被父栈读取并传递，是父子栈解耦的关键；C 错误：ROS 支持对整个父栈统一设置回滚策略，当子栈创建/更新失败时，父栈会按策略自动回滚整个嵌套层级的资源，无需手工处理；D 正确，通过 OSS + 版本号或参数化 URL 即可轻松实现子模板版本管理。',ref:'help.aliyun.com/zh/ros/best-practices/nested-stacks'},
  {id:'iac05',module:'IaC与运维编排',type:'single',question:'某团队用 ROS 部署了生产 VPC、ECS、RDS 后，运维同事在控制台手工修改了 ECS 安全组规则，导致模板声明与真实资源配置不一致。若希望 ROS 快速识别哪些资源存在"模板与实际不一致"的漂移并输出差异报告，应使用以下哪项功能？',options:['删除保护（Deletion Protection）','回滚策略（Rollback Policy）','漂移检测（Drift Detection）','变更集（Change Set）'],answer:[2],explanation:'漂移检测（Drift Detection）是 ROS 专门用于"检测模板描述的期望状态 vs 实际云上资源的真实状态是否一致"的能力，可针对整个栈或单个资源执行检测，报告会标记 Drifted/InSync 并逐字段列出差异属性（例如安全组被手工新增了一条入方向规则）。删除保护是避免误删，回滚策略是创建/更新失败时处理，变更集是更新前预演，三者均不是用来检测手工漂移的。',ref:'help.aliyun.com/zh/ros/user-guide/drift-detection'},
  {id:'iac06',module:'IaC与运维编排',type:'single',question:'某业务使用 ROS 管理 20+ 台核心 ECS 与 RDS 主实例，管理员担心误操作执行"删除栈"会导致数据被清空。以下哪种做法最符合 ROS 的官方最佳实践来避免误删关键资源？',options:['把所有资源加入回收站，不做其他配置','对栈开启"删除保护（Deletion Protection）"并对关键 RDS/OSS 等资源在模板中设置 DeletionPolicy=Retain','将 RAM 删除权限只授权给实习生账号','删除前先在本地备份一份快照即可'],answer:[1],explanation:'两层防护是最佳实践：栈级别的"删除保护"可在控制台/API 层面阻止 DeleteStack 调用，除非先手动关闭保护；资源级别的 DeletionPolicy=Retain/Snapshot 则在删除栈成功时保留资源或生成快照，避免模板层误删数据。A 回收站作用有限；C 将删除权授给高风险对象违背安全；D 仅依赖手工快照无法阻止误删造成的业务中断。',ref:'help.aliyun.com/zh/ros/user-guide/deletion-protection'},
  {id:'iac07',module:'IaC与运维编排',type:'judge',question:'在 ROS 中创建栈时若开启了"创建失败回滚（Rollback on Failure）"，当任意资源创建失败时，ROS 会自动撤销已创建的资源并恢复到创建前的状态，因此不会留下残留的半创建资源。',options:['正确','错误'],answer:[0],explanation:'ROS 创建失败回滚是生产推荐配置：开启后一旦出现资源创建失败事件，编排引擎会按依赖反序执行 DELETE 操作清理已创建成功的资源（对带 DeletionPolicy=Retain 的资源按策略处理），避免用户账号中留下孤儿资源、造成额外计费或后续同名冲突。更新阶段同理可设置"更新失败回滚"。',ref:'help.aliyun.com/zh/ros/user-guide/rollback-stack'},
  {id:'iac08',module:'IaC与运维编排',type:'multi',question:'关于 ROS 自定义资源（Custom Resource，通过 ALIYUN::FC::Invocation 或 ROS::CustomResource 触发函数计算 FC）的典型使用场景，以下哪些是正确的？',options:['当 ROS 原生暂不支持某新产品/新 API 时，可通过自定义资源编写 FC 函数去调用相应 OpenAPI，将"Create/Update/Delete"生命周期嵌入 ROS 栈管理','在创建 ECS/RDS 等资源后，自定义资源可触发 FC 完成初始化脚本、写入配置中心、推送配置到 CMDB 等"资源后置动作"，并在栈删除时联动清理','自定义资源被 ROS 视为普通资源，支持 DependsOn、支持回滚、支持 Outputs 返回值，可与原生资源混合编排','自定义资源执行逻辑完全在 ROS 引擎内部同步完成，不需要额外开通函数计算 FC 服务'],answer:[0,1,2],explanation:'A 正确，自定义资源是 ROS 扩展资源覆盖面的标准手段；B 正确，常被用作"资源后处理钩子"串联发布流程；C 正确，自定义资源具备与原生资源一致的生命周期语义，便于与 DependsOn、Outputs 协同；D 错误：自定义资源的实际逻辑由用户的 FC 函数承载，必须先开通函数计算并授权 ROS 调用 FC 的 RAM 角色，ROS 只是通过 HTTP/FC 回调协议收发信号，不会内置用户的业务逻辑。',ref:'help.aliyun.com/zh/ros/developer-reference/custom-resource'},
  {id:'iac09',module:'IaC与运维编排',type:'single',question:'在 Terraform HCL 中，用于"读取阿里云已存在资源的属性（不创建/修改资源），例如根据名称找到指定 VPC 的 ID 并引用到其他 resource 中"的代码块是以下哪一项？',options:['variable "vpc_name" { ... }','data "alicloud_vpcs" "default" { ... }','resource "alicloud_vpc" "this" { ... }','locals { ... }'],answer:[1],explanation:'data 块（数据源）用于只读查询已有资源的属性并将其暴露给后续 resource 引用，典型场景是按 name/tag 查询 VPC/VSwitch/SLB 等基础设施。variable 是输入参数；resource 才是声明创建/管理资源；locals 是局部变量计算表达式，均不具备"查询已存在资源"能力。',ref:'help.aliyun.com/zh/terraform/getting-started'},
  {id:'iac10',module:'IaC与运维编排',type:'multi',question:'关于 Terraform State（状态文件）在阿里云 Provider 场景下的最佳实践，以下哪些说法是正确的？',options:['官方推荐将 State 存储到远程 Backend（例如 OSS Bucket + DynamoDB 风格的 OTS 表锁），避免多人协作时本地 state 覆盖与丢失','多人协作前必须先锁定 state，OSS Backend 下可通过开启"OSS 版本控制 + 对象锁"并使用 locking 配置让 terraform apply 自动互斥','state 文件中可能包含明文敏感字段（如数据库 initial password、AK/SK），因此不能直接提交到 Git，远程 Backend 也应开启服务端加密与最小权限 RAM 访问','当 state 损坏时可以直接删除 terraform.tfstate，再执行 apply 即可自动重建，不会对线上资源造成任何影响'],answer:[0,1,2],explanation:'A 正确，远程 Backend 是 Terraform 协作的基石，阿里云社区推荐使用 OSS 作为 state 存储；B 正确，结合 OTS（表格存储）或 OSS 对象锁实现 state 互斥写入，避免两人同时 apply 破坏状态；C 正确，state 可能敏感，必须加密 + 最小权限 + 不入库；D 错误：直接删除 state 会导致 Terraform 完全忘记其管理的资源，再 apply 会尝试重建同名资源或与线上冲突，正确做法是从备份恢复或用 terraform import 将线上资源重新导入 state。',ref:'help.aliyun.com/zh/terraform/best-practices/state-management'},
  {id:'iac11',module:'IaC与运维编排',type:'multi',question:'关于阿里云 ROS（资源编排服务）与 Terraform（阿里云 Provider）的使用对比，以下说法正确的有？',options:['ROS 模板原生支持 JSON / YAML，Terraform 采用 HCL 语言','两者都支持"变更预演"（ROS 变更集 Change Set / Terraform Plan）再执行','Terraform 的 State 必须存储在本地磁盘，ROS 不需要维护 State','两者都支持通过嵌套栈 / Module 对模板进行模块化复用'],answer:[0,1,3],explanation:'A 正确，模板格式如上；B 正确，ROS 变更集与 terraform plan 都是先展示要 Create/Update/Delete 的资源再落盘执行；C 错误：Terraform State 官方推荐远程 backend（阿里云 OSS / Terraform Cloud / Consul 等），避免本地锁冲突与丢失；D 正确，ROS 嵌套栈 + Terraform Module 都是常用的复用手段。',ref:'help.aliyun.com/zh/ros/'},
  {id:'iac12',module:'IaC与运维编排',type:'multi',question:'关于 Terraform HCL 的核心块 resource、variable、output、locals，以下哪些描述是正确的？',options:['resource：声明要创建/管理的云资源（如 alicloud_instance、alicloud_vpc），其格式为 resource "<provider_type>" "<local_name>" { ... }，可通过 <type>.<name>.<attr> 被其他资源引用','variable：声明输入参数，支持 type/description/default/validation/sensitive 等字段，sensitive=true 的变量在日志中会被掩码，适合存放口令等敏感值','output：声明执行 terraform apply 后对外输出的值，通常用于返回公网 IP、RDS Endpoint 给上层 Module 或 CLI 查看，配合 depends_on 可控制输出顺序与依赖','locals：局部计算变量，允许用表达式组合 variable/data/resource 的值并在模块内多次复用，避免相同表达式在多处重复书写'],answer:[0,1,2,3],explanation:'A 正确，resource 是 Terraform 管理基础设施的核心抽象；B 正确，variable 是模块对外接口，validation 与 sensitive 是生产必备字段；C 正确，output 既用于人读也用于父子 Module 传参，depends_on 可显式声明对某资源就绪的前置依赖；D 正确，locals 类似"代码层常量"，常用于计算名称前缀、打标签、拼接 ARN 等可复用表达式。',ref:'help.aliyun.com/zh/terraform/developer-reference/hcl'},
  {id:'iac13',module:'IaC与运维编排',type:'single',question:'在 Terraform 项目中声明阿里云 Provider 时，以下哪种版本约束写法最符合生产可复现的最佳实践？',options:['不指定版本，直接使用最新版即可','provider "alicloud" { version = "latest" }','terraform { required_providers { alicloud = { source = "aliyun/alicloud" ; version = ">= 1.0.0" } } }','terraform { required_providers { alicloud = { source = "aliyun/alicloud" ; version = "~> 1.212.0" } } }'],answer:[3],explanation:'生产环境必须锁死 Provider 主版本以避免意外行为。D 使用 Pessimistic Constraint "~> 1.212.0"，表示允许 1.212.x 下的补丁升级但不跨越次版本，兼顾安全补丁与兼容性；C 的">="会拉取最新大版本，可能引入破坏性变更；A/B 完全不锁定版本会导致构建不可复现，出现不兼容的新版资源参数时会直接造成 apply 失败。',ref:'help.aliyun.com/zh/terraform/product-overview/provider-versions'},
  {id:'iac14',module:'IaC与运维编排',type:'multi',question:'关于 Terraform 的三大命令 plan、apply、destroy，在日常使用中的语义与推荐做法，以下哪些说法是正确的？',options:['terraform plan：仅生成执行计划并打印将新增/修改/销毁的资源及字段差异，默认不落地变更，可通过 -out=tfplan 保存到文件供后续 apply 精确重放','terraform apply：执行当前配置以达到期望状态，若配合保存过的 plan 文件 apply tfplan，可保证执行内容与之前 plan 完全一致，避免"计划与实际不同步"的风险','terraform destroy：销毁配置中管理的所有资源，生产环境强烈建议先执行 terraform plan -destroy 或 destroy 前预览，且不要与 -auto-approve 直接搭配脚本','三者均会自动生成并上传变更集到阿里云 ROS，以便在控制台二次审批后再执行'],answer:[0,1,2],explanation:'A 正确，plan 是 Terraform 的"预演"，配合 -out 是流水线中的标准用法；B 正确，plan+apply 两步走避免中间有人改代码导致计划漂移；C 正确，生产 destroy 必须先看清范围，-auto-approve 只推荐在受严格控制的 CI 环境内使用；D 错误：Terraform 与 ROS 是两套独立 IaC 工具，Terraform 并不会自动向 ROS 上传变更集，也不存在控制台二次审批的原生机制。',ref:'help.aliyun.com/zh/terraform/getting-started/commands'},
  {id:'iac15',module:'IaC与运维编排',type:'single',question:'在 Terraform 中，需要用新版本 AMI/镜像重建 ECS 实例，但要求"先创建新实例并通过健康检查、再删除旧实例"，以避免服务中断。应在 resource 块中配置 lifecycle 的哪个参数？',options:['prevent_destroy = true','create_before_destroy = true','ignore_changes = [tags]','replace_triggered_by = []'],answer:[1],explanation:'create_before_destroy=true 会让 Terraform 在替换资源时按"先建新→切流量/就绪→再删旧"顺序执行，是实现零停机滚动替换的基础，依赖资源的 Name/ID 允许重复或支持唯一后缀。prevent_destroy 是阻止 destroy；ignore_changes 是忽略某些字段漂移；replace_triggered_by 是其他资源变更时触发重建，三者均不具备"先建后删"语义。',ref:'help.aliyun.com/zh/terraform/best-practices/lifecycle'},
  {id:'iac16',module:'IaC与运维编排',type:'multi',question:'关于 Terraform 的 Module 与 Workspace 的用法，以下哪些说法是正确的？',options:['Module 是 HCL 代码的复用单元，可封装一段 VPC 网络基线、应用基线、RDS 基线并以 source=本地路径 / Git 仓库 / Terraform Registry 引用，通过 variable 传参定制','Workspace 用于在"同一份配置代码"下隔离多套环境（dev/staging/prod），每切换 workspace 都对应独立的 state，从而避免开发与生产资源互相覆盖','为实现 dev/staging/prod 环境隔离，官方推荐只使用同一个 default workspace + 不同的 state 文件路径即可，Module/Workspace 没有必要','在大型团队中，推荐将 Module 版本化（打 Git Tag），在引用时通过 source="git::...?ref=v1.2.3" 锁定版本，避免上游 Module 变更破坏生产'],answer:[0,1,3],explanation:'A 正确，Module 是 Terraform 代码复用的标准机制；B 正确，Workspace 的设计初衷就是"同配置多环境"，可配合不同的 tfvars 文件传入不同规格/参数；C 错误：多环境隔离首推 Workspace（或更严格的"多目录多 root module"），仅靠改 state 文件路径容易引发误操作与权限错配；D 正确，Module 版本化 + 锁 ref 是企业落地的最佳实践，避免因上游 master 分支随意推送导致生产 apply 失败。',ref:'help.aliyun.com/zh/terraform/best-practices/modules-workspaces'},
  {id:'iac17',module:'IaC与运维编排',type:'judge',question:'Terraform 中 lifecycle.prevent_destroy = true 设置后，即便执行 terraform destroy 或因参数变化需要重建资源，Terraform 也会拒绝销毁该资源并报错，因此常用于 RDS、OSS 数据桶等核心数据资源，防止误删。',options:['正确','错误'],answer:[0],explanation:'prevent_destroy=true 是 Terraform 提供的"保护闸"：任何会导致该资源被删除（包括 destroy 和因不支持原地更新而触发的重建）的计划都会被 plan 阶段直接拒绝并报错，是保护生产数据不被误删除的低成本手段，常与 OSS Bucket、RDS 实例、KMS Key 等关键资源配合使用。',ref:'help.aliyun.com/zh/terraform/best-practices/lifecycle'},
  {id:'iac18',module:'IaC与运维编排',type:'single',question:'阿里云运维编排服务 OOS 提供了多种模板来源。关于"公共模板"与"自定义模板"的区别，以下哪种描述最准确？',options:['公共模板是 OOS 官方预置的高频运维脚本（如批量升级软件、重置密码、打补丁等），可直接使用但不可编辑；自定义模板是用户基于 JSON/YAML 自行编写并保存在账号下的模板，可版本化与授权给 RAM 子账号','公共模板只能用于 ECS，自定义模板只能用于 RDS','公共模板需要额外付费，自定义模板免费','自定义模板必须托管在函数计算 FC 中，公共模板保存在 OSS'],answer:[0],explanation:'OOS 公共模板是阿里云官方维护的最佳实践库，覆盖常见运维动作（如批量执行命令、定时升级、报警联动），用户无需编写即可直接执行；自定义模板则由用户按照 OOS 模板语法（Tasks/Parameters/Outputs 等）编写，适合企业内沉淀标准化运维流程，并可通过 RAM Policy 授权给指定角色或子账号。其余选项在范围、计费、存储位置上均与产品定义不符。',ref:'help.aliyun.com/zh/oos/product-overview/templates'},
  {id:'iac19',module:'IaC与运维编排',type:'single',question:'在 OOS 自定义模板中，希望同时实现如下能力：① 执行 ECS runCommand 跑脚本；② 调用云产品 OpenAPI（如调用 RDS CreateBackup）；③ 人工审批后再继续执行；④ 等待某个条件满足再进入下一阶段。下列哪组 OOS 任务类型（TaskType）组合能正确覆盖上述需求？',options:['ACS::RunCommand、ACS::ExecuteAPI、ACS::Approve、ACS::WaitFor','ACS::Notify、ACS::Waiter、ACS::Email、ACS::Sleep','ACS::FC、ACS::SLS、ACS::ECS、ACS::END','ACS::Loop、ACS::Choice、ACS::End、ACS::Sleep'],answer:[0],explanation:'OOS 内建任务类型中，ACS::RunCommand 对应调用云助手在 ECS 内执行脚本；ACS::ExecuteAPI 对应调用任意阿里云 OpenAPI（可通过 API Explorer 自动生成参数）；ACS::Approve 对应审批任务（人工或钉钉通知），通过后置动作继续；ACS::WaitFor 对应轮询某个资源状态直到满足条件或超时。其余组合中的任务类型均不能完整覆盖题干中的四项能力。',ref:'help.aliyun.com/zh/oos/user-guide/task-types'},
  {id:'iac20',module:'IaC与运维编排',type:'multi',question:'关于 OOS 的批量运维与目标实例选择能力，以下哪些说法是正确的？',options:['OOS 执行批量命令时可通过"实例标签（Tag Key/Value）"作为目标过滤器动态选择 ECS 实例，无需手写实例 ID 列表，适合按业务线/环境分批运维','OOS 支持速率控制（MaxConcurrency 并发数/百分比），可设定如"同时 10%"或"最多 5 台"并行执行，避免一次性压垮业务','OOS 支持错误阈值（MaxErrors）控制，当失败数达到阈值时自动停止后续任务执行，避免坏脚本扩大故障面','OOS 批量运维只能在当前地域执行，无法跨地域选择实例并统一分发命令'],answer:[0,1,2],explanation:'A 正确，基于标签的动态目标选择是 OOS 相对手工写 ID 列表的最大优势；B 正确，速率控制可实现灰度分批执行，结合健康检查更稳妥；C 正确，MaxErrors 能尽早终止故障扩散，是批量变更的必备参数；D 错误：OOS 支持跨地域执行，模板和执行中可指定 RegionId 列表或在目标中包含多地域，适合全球化业务统一运维。',ref:'help.aliyun.com/zh/oos/operation-and-maintenance/batch'},
  {id:'iac21',module:'IaC与运维编排',type:'multi',question:'关于 OOS 的定时运维（Cron 触发）与跨地域执行能力，以下哪些描述是正确的？',options:['OOS 可创建"定时运维（CronTrigger）"任务，按标准 Cron 表达式周期性触发指定模板执行，典型场景如每日凌晨备份、每周重启、每月补丁','OOS 定时运维依赖云监控的 Cron 服务，不能脱离云监控单独创建','OOS 跨地域执行可通过模板参数或 targets 中设置多个 RegionId，在一次执行中并发或串行将同一运维动作下发到多个地域的实例，实现统一治理','跨地域执行时，OOS 会自动将模板脚本与 OSS 依赖对象复制到每个目标地域的本地临时存储，避免跨地域下载脚本的额外流量'],answer:[0,2],explanation:'A 正确，定时运维是 OOS 高频能力，支持"日/周/月"等 Cron 表达式；B 错误：OOS 提供自有的 CronTrigger/Trigger 机制，无需依赖云监控即可创建定时任务，两者是解耦的产品；C 正确，跨地域是企业统一运维的刚需，OOS 原生支持指定多 RegionId 批量下发；D 错误：OOS 不会自动把脚本复制到每地域临时存储，脚本若需要大文件建议放在目标地域就近的 OSS Bucket 中，题干"自动复制"属于伪能力。',ref:'help.aliyun.com/zh/oos/operation-and-maintenance/scheduled-ops'},
  {id:'iac22',module:'IaC与运维编排',type:'multi',question:'关于 OOS 与云监控报警联动的典型闭环用法，以下哪些说法是正确的？',options:['云监控针对 ECS CPU/内存/磁盘阈值触发报警时，可在报警通知动作中调用 OOS 执行预定义模板（如自动扩容节点、重启进程、清理磁盘），实现自动自愈','联动模板中通常需要接收报警事件参数（instanceId、regionId、指标值等）作为模板 Parameters，OOS 任务中可据此精确定位异常实例并执行动作','为避免误自愈，可在 OOS 模板中前置"人工审批 + 条件分支（ACS::Choice）"环节：若属于高危动作则进入审批，低风险则自动执行','云监控报警只能发钉钉/短信通知，无法直接触发 OOS 模板执行，必须自行购买中间件实现对接'],answer:[0,1,2],explanation:'A 正确，报警→自愈是云监控 + OOS 的经典落地路径，也是官方推荐的"事件驱动运维"最佳实践；B 正确，云监控触发 OOS 时会把事件字段透传到模板 Parameters，instanceId/regionId/metricName 等可直接被 Tasks 使用；C 正确，搭配 Approve 任务与 Choice 分支可以按风险等级分层处置，既提效又控风险；D 错误：云监控报警规则中可直接配置"OOS 执行模板"作为通知方式，无需用户自建中间件。',ref:'help.aliyun.com/zh/oos/scenarios/cloudmonitor-alarm-action'},

  // ========== 5. 可观测与监控 obs01~20（9 单 + 9 多 + 2 判） ==========
  {id:'obs01',module:'可观测与监控',type:'multi',question:'关于阿里云 SLS（日志服务）的核心资源层级 Project、Logstore 与 Shard，以下哪些说法是正确的？',options:['Project 是 SLS 的顶级命名空间，同一账号下全局唯一，通常按业务线或大环境（如 prod-app1、test-biz2）进行隔离','Logstore 是 Project 下的日志采集与存储单元，对应一类日志主题，每个 Logstore 独立配置采集、索引、保留时长与投递','Shard 是 Logstore 内的吞吐分区，每个 Shard 提供 5MB/s 写入与 10MB/s 读取能力，可手动分裂或合并扩展吞吐容量','一个 Logstore 只能绑定一个 Shard，不允许动态分裂，若吞吐不够必须重新新建 Logstore'],answer:[0,1,2],explanation:'A 正确，Project 提供资源与权限的一级隔离边界，命名全局唯一；B 正确，Logstore 是日志主题级别的存储单元，索引、TTL、投递、消费位点均挂在 Logstore 上；C 正确，Shard 按吞吐配额切分，是水平扩展的最小单位；D 错误，Logstore 支持多个 Shard 并可手动分裂/合并或开启自动分裂，无需重建 Logstore。',ref:'help.aliyun.com/zh/sls/product-overview/basic-concepts'},
  {id:'obs02',module:'可观测与监控',type:'single',question:'在 SLS 中为同一批 ECS 服务器统一采集 /var/log/nginx/access.log 到指定 Logstore，官方推荐先将 ECS 按标签或 IP 列表归组，再在该组上批量安装并配置采集配置。上述"归组"能力对应的 SLS 资源名称是？',options:['机器组（Machine Group）','实例池（Instance Pool）','采集通道（Collection Channel）','日志池（Log Pool）'],answer:[0],explanation:'机器组（Machine Group）是 SLS 管理采集端点的标准资源：可按 IP 列表或 ECS 标签（Tag）动态匹配一批 ECS/服务器，配合 Logtail（日志采集 Agent）实现批量下发采集配置、版本统一管理和心跳监控。其余三个名称均不是 SLS 的官方资源名。',ref:'help.aliyun.com/zh/sls/user-guide/machine-group-overview'},
  {id:'obs03',module:'可观测与监控',type:'single',question:'接入阿里云 ARMS 应用监控时，针对标准 Java/Spring Boot 应用，无需修改业务代码即可完成字节码增强、自动埋点的官方推荐方式是？',options:['通过 java -javaagent:/path/to/ArmsAgent/arms-bootstrap-1.0.0-SNAPSHOT.jar -jar app.jar 的方式，在启动参数中挂载 ARMS Java Agent','在每个 Controller 方法上手动添加 @ARMS 注解完成埋点','下载 ARMS SDK 并在 main 方法中显式调用 ArmsClient.init()','必须打包时引入 ARMS Maven 插件重写字节码，运行时不需要额外参数'],answer:[0],explanation:'ARMS 应用监控对 Java 提供零侵入 Agent 方案，通过 -javaagent 启动参数挂载官方 arms-bootstrap Agent，即可自动完成 Spring MVC/Dubbo/MySQL/Redis/Tomcat 等常见组件的字节码增强埋点，无需改代码、无需 SDK 初始化。B/C/D 都属于侵入或错误做法。',ref:'help.aliyun.com/zh/arms/quick-start-java-applications'},
  {id:'obs04',module:'可观测与监控',type:'multi',question:'关于 ARMS 应用监控的核心能力：调用链（Distributed Trace）、异常分析与慢 SQL 分析，以下哪些描述是正确的？',options:['调用链 Trace 基于 OpenTracing/W3C TraceContext 语义，可按 TraceId 串联一次请求跨多服务、多中间件的完整调用耗时与拓扑，支持按状态码/耗时过滤','异常分析功能会自动聚合应用抛出的异常堆栈，按异常类型、接口、版本、时间维度统计出现次数与影响用户数，并可直接下钻到关联 Trace','慢 SQL 分析通过 Agent 自动抓取 JDBC 执行超过阈值的 SQL 语句、参数、执行时长与调用来源方法，辅助定位数据库层性能瓶颈','慢 SQL 分析必须在数据库侧开启 General Log 才能工作，ARMS 侧无法自动拦截'],answer:[0,1,2],explanation:'A 正确，调用链是 APM 的核心能力，拓扑与瀑布图是排障常用入口；B 正确，异常聚合与趋势统计是 ARMS 告警前的主动发现手段，支持直接跳 Trace；C 正确，JDBC 层埋点由 Java Agent 字节码增强实现，不依赖数据库侧配置；D 错误，ARMS 慢 SQL 抓取是应用侧 JDBC 拦截，完全不需要开启数据库 General Log，后者对数据库性能影响较大不建议生产长期开启。',ref:'help.aliyun.com/zh/arms/user-guide/use-distributed-tracing'},
  {id:'obs05',module:'可观测与监控',type:'single',question:'在阿里云 ACK 集群中希望一键托管式接入 Prometheus 监控（含预装 Grafana 大盘、常用 Exporter、告警模板），官方推荐的入口与方式是？',options:['自行在集群中用 Helm 安装开源 prometheus-operator','在 ACK 控制台"运维管理→Prometheus 监控"页面一键启用托管版 Prometheus for ACK，由阿里云负责托管采集端与存储查询','在每台节点上手动 yum 安装 node_exporter 并配置远程写入自建 Prometheus','必须购买独立的 ECS 自建 Prometheus + Grafana 才能对接 ACK'],answer:[1],explanation:'托管版 Prometheus for ACK 是阿里云提供的一体化能力：在 ACK 控制台一键启用后，系统会自动安装 node-exporter、kube-state-metrics、Blackbox 等基础 Exporter 并集成 Grafana 大盘、告警规则模板，存储与查询由托管侧统一承担，运维成本与稳定性都显著优于自建 Helm/ECS 方案。',ref:'help.aliyun.com/zh/arms/prometheus/quick-start-ack-managed-prometheus'},
  {id:'obs06',module:'可观测与监控',type:'multi',question:'关于 ACK 托管版 Prometheus 中 ServiceMonitor 与 PodMonitor 的典型用法，以下哪些说法是正确的？',options:['两者均由 kube-prometheus-stack（Prometheus Operator）定义，用于声明式地告诉 Prometheus 要采集哪些 Service 或 Pod 的 /metrics 端点','ServiceMonitor 通过匹配 Service 的 labels 与 endpoints 端口，间接采集后端 Pod 指标，适合 Deployment/StatefulSet 等有稳定 Service 暴露端口的服务','PodMonitor 直接匹配 Pod 的 labels 与容器端口，无需经过 Service，适合 Job、Sidecar 或无 Service 的临时任务型指标暴露','ServiceMonitor 与 PodMonitor 不允许自定义 relabel 与 metricRelabel，所有参数必须沿用默认值'],answer:[0,1,2],explanation:'A 正确，二者是 Prometheus Operator 标准 CRD，是 Prometheus 采集侧的声明式入口；B 正确，ServiceMonitor 关联 Service，契合传统服务暴露模式；C 正确，PodMonitor 面向无 Service 或希望绕过 LB 直接抓 Pod 的场景，Job/CronJob 监控常用；D 错误，两者 spec 中均支持 relabelings、metricRelabelings、scrapeTimeout、scrapeInterval 等原生 Prometheus 配置项，具备完整自定义能力。',ref:'help.aliyun.com/zh/arms/prometheus/user-guide/use-servicemonitors-and-podmonitors'},
  {id:'obs07',module:'可观测与监控',type:'single',question:'阿里云 SLS 日志服务中，要对一个 Logstore 的日志做全文关键词检索 + SQL 字段聚合分析，必须先在控制台开启以下哪项配置？',options:['日志分区（Shard）自动分裂','索引（全文索引 + 字段索引）','开通日志投递到 OSS','开启消费组（Consumer Group）'],answer:[1],explanation:'SLS 的查询分析功能完全依赖索引：全文索引决定哪些关键词可以被检索，字段索引（标注字段类型 long/double/text/json）决定 SQL 能否按列 SELECT/GROUP BY/AGG。Shard 自动分裂是吞吐扩展、投递 OSS 是离线归档、消费组是实时流式消费，三者都不影响"查询/SQL"能力。',ref:'help.aliyun.com/zh/sls/user-guide/configure-index'},
  {id:'obs08',module:'可观测与监控',type:'judge',question:'在 SLS 索引配置中，为字段 request_time 选择的类型是 long（长整型）后，查询时仍然可以使用 SQL 的 avg()、percentile() 等数值聚合函数对该字段做统计，因此 long 与 double 两种字段类型在数值聚合能力上完全等价、没有任何差异。',options:['正确','错误'],answer:[1],explanation:'虽然 long 和 double 都支持数值聚合（sum/avg/min/max），但两者存储与取值范围不同：long 为 64 位整数无小数，适合毫秒级时间戳、计数、字节数；double 为 64 位浮点，支持小数但精度有限，适合比率、温度、耗时秒数等浮点指标。对带小数的耗时字段若误配 long 会丢失小数部分导致统计失真，因此两者并不完全等价，题干断言错误。',ref:'help.aliyun.com/zh/sls/user-guide/field-type'},
  {id:'obs09',module:'可观测与监控',type:'multi',question:'关于 SLS 的数据投递（Ship/Data Transformation 导出）与消费组 Consumer Group，以下哪些说法是正确的？',options:['SLS 支持把 Logstore 中的日志按指定格式（JSON/CSV/Parquet 等）自动、增量投递到 OSS Bucket，用于离线数仓或低成本长期归档','SLS 支持投递到 MaxCompute 表，按分区字段分区写入，对接 DataWorks 做 ETL 与数仓建模','Consumer Group 是 SLS 提供的实时流式消费抽象：多个消费者实例同组协作消费同一 Logstore，各 Shard 内严格顺序、组间位点由 SLS 服务端持久化保存，支持自动断点续传','Consumer Group 与投递 OSS/MaxCompute 本质是同一种能力，只是名称不同'],answer:[0,1,2],explanation:'A 正确，OSS 投递是 SLS 冷热分层的官方方案，支持压缩与列式格式；B 正确，MaxCompute 投递用于大数据分析链路，可做字段映射与分区；C 正确，Consumer Group 是类 Kafka 消费组模型，服务端保存 checkpoint，适合自建实时计算、告警、转发下游；D 错误，投递是 SLS 托管的异步批量离线导出，消费组是用户侧实时拉流消费，两者模型与时延、控制权均不同，并非同能力别名。',ref:'help.aliyun.com/zh/sls/user-guide/ship-data-to-oss'},
  {id:'obs10',module:'可观测与监控',type:'single',question:'ARMS 前端监控（Browser/小程序监控）通过在 HTML 或小程序入口注入一段 JS SDK 来采集真实用户体验数据。以下哪项不属于 ARMS 前端监控默认采集的核心指标？',options:['页面加载性能（FP/FCP/LCP/DOM Ready/Load）、JS 异常与 API 错误','API/接口请求耗时、成功率与慢接口明细','PV/UV、地域、设备、浏览器分布','服务器端 JVM 堆内存与 GC 次数'],answer:[3],explanation:'前端监控采集的是浏览器侧/客户端侧真实用户体验数据：页面性能、JS 错误、接口调用、PV/UV、维度分布均为默认能力；而 JVM 堆内存与 GC 属于服务端 Java 应用监控（ARMS 应用监控 Java Agent）的指标域，不是前端 SDK 能采集到的内容。',ref:'help.aliyun.com/zh/arms/product-overview/frontend-monitoring'},
  {id:'obs11',module:'可观测与监控',type:'judge',question:'ARMS 自定义监控支持用户通过 SDK 或 API 把任意业务指标（如订单支付金额、库存剩余、验证码发送次数）上报并配置大盘与阈值告警；但上报的自定义指标只能是正整数，无法上报带小数的浮点数。',options:['正确','错误'],answer:[1],explanation:'ARMS 自定义监控（Prometheus 兼容与 ARMS 自定义指标 SDK）支持 long、double 等多种数值类型，既可以上报整数计数，也可以上报浮点平均值、比率（如支付成功率 98.5%）、平均耗时等带小数的数据并进行四则运算与聚合，题干中"只能是正整数，无法上报浮点数"错误。',ref:'help.aliyun.com/zh/arms/user-guide/custom-monitoring-overview'},
  {id:'obs12',module:'可观测与监控',type:'multi',question:'关于 ARMS 的自定义监控能力（业务指标上报与大盘），以下哪些描述是正确的？',options:['可通过 ARMS 官方 Java/Node.js/Go/Python SDK 或 HTTP API，按"指标名 + 标签 + 时间戳 + 数值"格式上报业务指标','上报后的自定义指标可在 ARMS/Grafana 中配置折线图、饼图、TopN 等大盘组件，并支持按标签维度下钻与过滤','自定义指标可以与 ARMS 应用监控的系统指标（QPS/RT/错误率）组合在同一告警规则中，形成业务+系统的联合阈值判断','自定义指标上报后只能查看 1 小时以内数据，不能做历史趋势分析'],answer:[0,1,2],explanation:'A 正确，多语言 SDK 与 HTTP API 是上报的两类标准入口；B 正确，ARMS 大盘与 Grafana 均可直接对接自定义指标数据源并做维度过滤；C 正确，ARMS 告警规则支持多指标组合判断（如系统 RT 上涨且订单支付率下降时触发），是业务告警的常用做法；D 错误，自定义指标存储周期由托管版 Prometheus 策略决定（通常 15 天起步，可配置更长），可用于长期趋势分析，并非仅保留 1 小时。',ref:'help.aliyun.com/zh/arms/user-guide/report-custom-metrics'},
  {id:'obs13',module:'可观测与监控',type:'single',question:'在 ACK 托管版 Prometheus 中，需要对集群内常见资源状态（Deployment 副本数是否达标、Pod 是否 CrashLoopBackOff、Node 是否 Ready、HPA 目标值等）做大盘与告警，应优先启用以下哪个官方推荐的 Exporter？',options:['Blackbox Exporter','kube-state-metrics','node-exporter','Redis Exporter'],answer:[1],explanation:'kube-state-metrics 由 Kubernetes 社区维护，专门把 Deployment/DaemonSet/StatefulSet/Node/Pod/HPA 等 API 对象的期望态与当前态转化为指标暴露（如 kube_deployment_spec_replicas、kube_pod_status_phase、kube_node_status_condition），是资源状态大盘与告警的基石。Blackbox 用于黑盒探测（HTTP/ICMP/DNS），node-exporter 用于节点 OS 指标，Redis Exporter 仅针对 Redis。',ref:'help.aliyun.com/zh/arms/prometheus/user-guide/kube-state-metrics'},
  {id:'obs14',module:'可观测与监控',type:'multi',question:'关于 ACK 托管版 Prometheus 中的常见 Exporter，以下哪些匹配是正确的？',options:['node-exporter：采集节点级 OS 指标（CPU/内存/磁盘使用率、网络吞吐、Load、inode 等），每个节点运行一个 Pod（常通过 DaemonSet 部署）','kube-state-metrics：采集 Kubernetes API 对象状态（副本数、Pod 阶段、Node Ready、PVC 绑定等），属于集群级单体 Deployment','Blackbox Exporter：通过白盒方式读取应用内部 /metrics 端口的业务指标，是最常用的业务指标采集器','Blackbox Exporter：通过黑盒方式从外部探测 HTTP/HTTPS、TCP、ICMP、DNS 等端点的可用性与响应延迟，常用于 Ingress 域名、数据库端口、外部 API 的可用性监控'],answer:[0,1,3],explanation:'A 正确，node-exporter 是每节点 OS 指标的事实标准，ACK 默认 DaemonSet 部署；B 正确，kube-state-metrics 是 K8s 控制面状态的专用 exporter，单实例或双实例高可用即可；C 错误，黑盒探测不读取内部 /metrics，白盒应用指标通常由 ServiceMonitor/PodMonitor 抓取应用自带的 /metrics；D 正确，Blackbox 的场景正是外部可达性监控，是 Ingress/SLB 健康性的重要补充。',ref:'help.aliyun.com/zh/arms/prometheus/user-guide/node-exporter'},
  {id:'obs15',module:'可观测与监控',type:'multi',question:'关于 ACK 托管版 Prometheus 的告警规则与 Grafana 大盘，以下哪些说法是正确的？',options:['告警规则支持以 PromQL 表达式定义阈值（如 CPU > 90% 持续 5 分钟），并可设置严重等级、持续时间、标签与注解','托管版 Prometheus 提供开箱即用的 ACK 集群总览、节点、Pod、Ingress、etcd 等官方预置 Grafana 大盘，无需从零搭建','Grafana 大盘中的变量（Variables）可以与 Prometheus 标签结合，实现按集群、命名空间、Deployment 下拉切换的多维度可视化','所有告警只能通过邮件通知，不支持钉钉、短信、Webhook 等渠道'],answer:[0,1,2],explanation:'A 正确，Alertmanager 规则的标准表达正是 PromQL + for 窗口 + labels/annotations；B 正确，ACK 托管 Prometheus 预置大盘数十张，是新手快速上量的首选；C 正确，Grafana 变量结合 label_values() 是实现下拉过滤的核心技巧，几乎所有生产大盘都使用；D 错误，托管版告警对接云监控通知渠道与 ARMS 告警管理，原生支持钉钉机器人、短信、邮件、语音、Webhook、企业微信等多种通知方式。',ref:'help.aliyun.com/zh/arms/prometheus/user-guide/use-alerting-rules'},
  {id:'obs16',module:'可观测与监控',type:'single',question:'阿里云云监控（Cloud Monitor，CM）的"应用分组"能力是多云产品统一监控的基础。关于其价值，以下哪项描述最准确？',options:['应用分组只能把同一地域的 ECS 归组，不能跨地域也不能包含非 ECS 资源','应用分组可将 ECS、RDS、SLB、OSS、Redis、ACK 等跨产品、跨地域的资源按业务系统统一归组，并在分组维度统一查看健康度、配置告警与大盘','应用分组仅用于展示页面美化，对告警与成本无任何实际作用','应用分组创建后不允许修改成员，资源变更时必须删掉重建'],answer:[1],explanation:'云监控的应用分组是按业务系统组织资源的核心抽象，支持跨产品、跨地域将 ECS/RDS/SLB/Redis/OSS/ACK 等资源统一分组，基于分组可批量配置告警、一键接入 Grafana、查看业务视角健康度与事件聚合，是实现"业务可观测"而非"单资源可观测"的第一步。A/C/D 都是对能力边界的错误缩小。',ref:'help.aliyun.com/zh/cm/user-guide/application-groups'},
  {id:'obs17',module:'可观测与监控',type:'multi',question:'关于可观测体系的告警降噪手段：告警分组（Grouping）、抑制（Inhibition）与静默窗口（Silence），以下哪些说法是正确的？',options:['告警分组可将同一业务同一时段内具有相同标签（如 namespace=trade、alertname=HighCPU）的多条告警合并为一条通知，避免钉钉群刷屏','告警抑制是指当某条高优先级告警（如 ACK Node NotReady）触发时，自动屏蔽该节点下属 Pod 产生的低优先级衍生告警，避免"雪崩式通知"让值班人员淹没在噪声中','静默窗口用于计划内变更（如凌晨升级、重启、压测）期间临时屏蔽指定标签的告警，过了窗口自动恢复，避免忘记重新开启告警','三种机制只能三选一使用，组合使用会导致告警丢失'],answer:[0,1,2],explanation:'A 正确，分组是 Alertmanager/云监控告警管理的标配能力，常见按 alertname+service 维度聚合；B 正确，抑制通过"源告警匹配→目标告警匹配"的规则矩阵，根因级告警屏蔽现象级告警，是降噪关键；C 正确，静默支持开始结束时间与标签过滤，变更窗口首选；D 错误，三者强烈建议组合使用：分组减通知条数、抑制去冗余、静默排计划变更，叠加后才能显著降低告警信噪比，不存在三选一的限制。',ref:'help.aliyun.com/zh/cm/user-guide/alert-management'},
  {id:'obs18',module:'可观测与监控',type:'single',question:'在阿里云告警通知渠道中，希望把 SLS/ARMS/Prometheus/云监控的告警统一派发到团队协作群，并可 @ 单人或全员，同时支持点击卡片跳转到告警详情页，应优先选择以下哪种通知方式？',options:['只使用短信，不使用其他渠道','钉钉机器人 Webhook（告警管理中配置钉钉群机器人，支持加签与 @）','仅在控制台浏览器弹窗通知','依赖 Linux cron 定时任务定期 grep 日志并发送邮件'],answer:[1],explanation:'钉钉机器人 Webhook 是阿里云告警体系官方支持的一等公民：云监控、SLS 告警、ARMS/Prometheus 告警管理中均可直接配置钉钉群自定义机器人，支持安全关键词、加签、@ 指定成员或 @all，并以卡片样式展示阈值、标签与详情跳转链接，是团队值班首选渠道。其余方式要么触达性差、要么信息密度低或需要自建。',ref:'help.aliyun.com/zh/cm/user-guide/notify-dingtalk-robot'},
  {id:'obs19',module:'可观测与监控',type:'multi',question:'关于 EventBridge 在可观测联动中的典型用法，以下哪些描述是正确的？',options:['EventBridge 可作为事件总线统一接收 SLS 告警、云监控告警、ARMS/Prometheus 告警事件，并通过规则路由到不同的下游（钉钉/短信/函数计算/OOS 运维模板）','通过 EventBridge 的事件模式匹配（Content-based Filter），可以把严重级别 critical 的告警单独走电话+钉钉双通道，warning 级别仅走邮件，实现分级通知','EventBridge 支持跨账号事件总线：生产账号的告警事件投递到运维中心账号的事件总线统一编排，满足多账号集中治理','EventBridge 只能转发阿里云产品内部事件，无法接收用户自定义业务事件（如订单失败、风控阻断）并联动告警'],answer:[0,1,2],explanation:'A 正确，EventBridge 是云原生事件路由中枢，是打通多产品告警的官方推荐底座；B 正确，事件模式基于 JSONPath 匹配 severity/topic 等字段并分别绑定不同目标，是分级告警的最佳实践；C 正确，跨账号/跨地域事件总线是企业集中治理的标配能力；D 错误，EventBridge 提供自定义事件总线 + PutEvents API/Schema Registry，可上报任意业务事件并结合规则触发告警、OOS 自愈或 FC 自动化处理。',ref:'help.aliyun.com/zh/eventbridge/product-overview/what-is-eventbridge'},
  {id:'obs20',module:'可观测与监控',type:'single',question:'某团队已搭建 SLS 日志、ARMS 应用监控、Prometheus 指标、云监控事件四道数据通路，希望实现"告警触发时自动打开 OOS 运维模板尝试自愈，并将执行结果回写钉钉群"的闭环。以下哪种产品联动顺序最符合官方推荐？',options:['SLS/ARMS/Prometheus/云监控 告警 → 通知仅发到值班人员邮件 → 值班人员人工 SSH 登录修复 → 手动回写钉钉','SLS/ARMS/Prometheus/云监控 告警 → EventBridge 事件总线统一接收 → 按级别与标签路由：低危转钉钉、高危同步触发 OOS 执行自愈模板 → OOS 执行结束回调 EventBridge/钉钉 Webhook 把结果回写群通知','各产品各自配置独立告警，互不联动，全靠值班人员肉眼串联','告警只通过短信发出，其他任何自动化动作都不允许'],answer:[1],explanation:'A 是纯人工流程效率低下；C 多通路各自为战无法形成闭环；D 仅短信无任何自动化。B 的"多源告警→EventBridge 统一编排→分级路由+自愈→结果回写"是官方推荐的可观测运维闭环架构：EventBridge 作为中枢解决多产品告警归一化与路由，OOS 承载自动化运维动作，钉钉作为人在环路的通知与结果回写入口，三者联动是 ACP DevOps 中"事件驱动运维"的标准范式。',ref:'help.aliyun.com/zh/eventbridge/scenarios/oos-automated-o-m'},

  // ========== 6. 发布与部署策略 rel01~14（6 单 + 7 多 + 1 判） ==========
  {id:'rel01',module:'发布与部署策略',type:'single',question:'某传统业务每次发布都先停掉老版本、再部署新版本，期间用户访问返回 502/503。该团队当前使用的发布策略与应改进的方向是？',options:['使用的是"滚动发布"，应改为"停机发布"以提高稳定性','使用的是"停机发布（Ramped Down/Redeploy）"，应改为滚动发布、蓝绿或灰度等零停机策略以消除用户可见的中断','使用的是"蓝绿发布"，应引入金丝雀机制以支持按比例放量','使用的是"灰度发布"，应降低灰度比例以减少影响面'],answer:[1],explanation:'题干描述的是典型的停机发布（先停旧再上新），特征就是发布窗口内存在用户可见的中断，对业务 SLA 伤害极大。正确改进方向是升级到 Deployment RollingUpdate 滚动发布、蓝绿或灰度发布等零停机策略，使新老版本平滑过渡，用户侧无感知。其余选项均把当前策略判断错误。',ref:'help.aliyun.com/zh/ack/best-practices/rolling-upgrade-best-practice'},
  {id:'rel02',module:'发布与部署策略',type:'multi',question:'在 ACK 集群中使用 Deployment 原生滚动更新（RollingUpdate）时，关于 maxSurge 与 maxUnavailable 两个参数的组合含义，以下哪些说法是正确的？',options:['maxSurge 表示滚动过程中允许超出期望副本数的最大 Pod 数量（或百分比），例如 maxSurge=25%、replicas=4 则最多允许多起 1 个新 Pod 再删旧 Pod','maxUnavailable 表示滚动过程中允许不可用的最大 Pod 数量（或百分比），控制"先删旧 Pod 再启新 Pod"的激进程度','当 maxSurge=0 且 maxUnavailable=1 时，滚动过程中不会出现超过期望副本数的 Pod，但每轮只能停掉 1 个旧 Pod 再启动 1 个新 Pod，发布速度较慢但容量无富余','若希望发布期间服务容量始终保持 100% 不下降，应设置 maxUnavailable=0 且 maxSurge>0（如 25%）'],answer:[0,1,2,3],explanation:'A 正确，maxSurge 定义"多起多少新 Pod 再腾位"的空间，是加速发布的核心参数；B 正确，maxUnavailable 定义"最多可以先停多少旧 Pod 让位"的风险阈值；C 正确，这是典型"保守型"配置——不扩容量、每轮只换一个，发布慢但资源占用不升；D 正确，maxUnavailable=0 保证滚动全程没有副本低于期望数，配合 maxSurge 给出新 Pod 启动窗口，是生产环境核心链路推荐的零容量下降配置。',ref:'help.aliyun.com/zh/ack/best-practices/rolling-upgrade-best-practice'},
  {id:'rel03',module:'发布与部署策略',type:'single',question:'某团队在 ACK 上希望实现按权重（5%→30%→100%）与按请求 Header（x-env=gray）两条维度同时生效的灰度发布，并希望发布过程中根据 Prometheus 成功率/延迟指标自动继续或回滚。以下哪种技术栈最符合官方最佳实践？',options:['仅用 Deployment 原生 RollingUpdate，自行写脚本改副本数','ACK Flagger + ASM（服务网格 Istio 托管版）：Flagger 监听指标驱动自动推进，ASM 提供权重与 Header/Cookie 路由能力','仅靠 Nginx rewrite 规则手工切流量','用阿里云 DNS 按解析比例切流量'],answer:[1],explanation:'题干的"双维度灰度+自动化指标驱动"正是 Flagger（ACK 官方集成的渐进式交付控制器）与 ASM 的组合所长：Flagger 负责 Canary 编排与 SLO 指标判定（成功率 P99 延迟等），ASM/Istio VirtualService 提供百分比权重与 Header/Cookie 细粒度路由，两者结合是 ACK 平台上推荐的灰度生产方案。A 只能做百分比替换无法按 Header 路由；C/D 手工维护容易出错且无自动化推进能力。',ref:'help.aliyun.com/zh/asm/use-cases/use-flagger-to-implement-canary-releases'},
  {id:'rel04',module:'发布与部署策略',type:'multi',question:'在云效 Flow / ACK 发布流水线中，以下哪些属于"发布质量门禁（Quality Gate）"的正确做法？',options:['接入 SonarQube：设置代码异味、安全漏洞、重复率与单元测试覆盖率阈值，低于阈值的构建直接失败，防止质量债务持续流入生产','对制品执行安全扫描：使用 OWASP Dependency Check 检查第三方依赖漏洞、Trivy 扫描容器镜像中的 OS 包与应用漏洞，高危漏洞（Critical/High）阻断发布','配置单元测试覆盖率门禁：JUnit（Java）、Pytest（Python）等生成覆盖率报告，当行覆盖率/分支覆盖率低于团队约定阈值时流水线失败','门禁只是"建议"而非"阻断"，为了不影响业务节奏，任何漏洞、异味和覆盖率不达标都可以直接放行到生产'],answer:[0,1,2],explanation:'A 正确，SonarQube 静态分析+覆盖率门禁是 DevOps 质量左移的基石，ACP 官方推荐作为必选阶段；B 正确，依赖与镜像漏洞若不提前阻断，生产运行时将成为供应链攻击入口，Trivy 和 OWASP DC 是云原生生态最主流的扫描工具；C 正确，单元测试覆盖率阈值是对回归能力的最低保障，通常核心模块要求行覆盖≥80%且分支覆盖同步达标；D 错误，门禁如果不阻断就失去了"闸"的意义，所有质量问题都会流入生产，违背质量门禁的设计初衷。',ref:'help.aliyun.com/zh/devops/user-guide/quality-gate'},
  {id:'rel05',module:'发布与部署策略',type:'single',question:'某线上发布事故复盘显示：代码回滚到了 v1.3，但镜像仍留在 v1.4、ConfigMap 已被新配置覆盖、数据库迁移脚本（DDL）中新增的字段没有回退，导致回滚后出现字段不匹配与反序列化异常。该事故最直接违反了以下哪条回滚原则？',options:['回滚只需回代码本身，其他维度无需关心','代码、镜像、配置、DB 迁移 schema 四者必须保持同一版本的一致性，回滚时整体同步回到上一稳定快照','回滚操作只需要在凌晨窗口执行即可，无需验证','回滚完成后不需要观察监控，让系统自然恢复'],answer:[1],explanation:'这是回滚四大要素"代码+镜像+配置+数据库 schema"一致性的典型反例：四者任一没有一起回到上一稳定版本，就会出现接口不匹配、字段缺失、配置读取失败等连锁问题。A/C/D 都是对回滚流程的错误认知，生产中回滚必须以"可复现的不可变版本快照"为单位，保证四元组的版本完全对齐。',ref:'help.aliyun.com/zh/devops/user-guide/rollback-policy'},
  {id:'rel06',module:'发布与部署策略',type:'multi',question:'关于"影子流量 / 流量镜像（Traffic Mirroring / Shadowing）"及其在发布验证中的作用，以下哪些说法是正确的？',options:['流量镜像会把线上真实请求无损复制一份，同时发送给正式版本（处理并响应）与影子新版本（仅处理不回写用户），用于在不影响用户的前提下对比新版本的正确性、延迟与异常率','影子流量验证属于"发布前置验证"，可在灰度放量之前发现新版本的兼容性问题，是风险最低的发布验证手段之一','ASM/Istio 的 VirtualService 支持 mirror/mirrorPercentage 字段，可把指定比例的生产流量镜像到另一个 Service/Subset，配合监控即可实现影子发布','流量镜像与灰度发布完全等价，镜像的请求也会写库并返回给用户，因此不能随意开启'],answer:[0,1,2],explanation:'A 正确，镜像/影子的本质就是"只处理不响应"，真实用户只收到主版本响应，影子侧仅用于离线比对；B 正确，它对用户零风险，是进入灰度前的最后一道真实流量验证关卡；C 正确，ASM 托管版 Istio 原生支持 mirror 字段与 mirrorPercentage，是影子发布的官方标准实现；D 错误，镜像请求默认不会写真实业务库（需应用层做好影子隔离或 DB/缓存侧 mock），也绝不会返回给用户，与灰度发布"真分流真响应"有本质区别。',ref:'help.aliyun.com/zh/asm/user-guide/traffic-mirroring'},
  {id:'rel07',module:'发布与部署策略',type:'judge',question:'发布流水线中，"版本不可变（Immutable Release）"原则要求：一旦某个构建版本通过了门禁、打包完成并推送到 ACR，后续若发现问题应重新构建新的版本号（或通过 tag 唯一性区分），严禁在不改变版本号/tag 的前提下覆盖已有制品后重新发布。',options:['正确','错误'],answer:[0],explanation:'该表述正确，正是版本不可变原则的核心。制品一旦产生就不应被覆盖修改，否则会出现"同名不同内容"的歧义，无法准确定位问题、无法可靠回滚、审计链也会断裂。生产环境应强制开启 ACR 仓库的"不可变镜像 tag"策略，发现问题时构建新版本号推进，而不是原地覆盖同一个 tag。',ref:'help.aliyun.com/zh/acr/user-guide/configure-immutable-tags'},
  {id:'rel08',module:'发布与部署策略',type:'multi',question:'关于"灰度发布（金丝雀）"和"蓝绿发布"的对比，下列说法正确的是？',options:['蓝绿发布需要同时维护两套容量对等的环境，切换时流量整体 0%→100% 切到新环境','灰度发布是按比例逐步放量（如 5%→20%→50%→100%），可在中间阶段观察监控指标后再决定继续或回滚','灰度发布和蓝绿发布都可以做到"零停机发布"','两种策略都必须依赖 Service Mesh（如 ASM/Istio）才能实现'],answer:[0,1,2],explanation:'A/B 是两策略的教科书级区别，均正确；C 正确，因为蓝绿切换是原子切换，灰度过程中新版本并行运行，两种用户侧都无停机；D 错误：蓝绿可以只靠 SLB 权重 / DNS 切流量实现，灰度可以靠 ACK 原生 Deployment 的 canary 控制器或 Nginx Ingress 注解切权重实现，Service Mesh 提供的是更细粒度的 Header/Cookie/用户维度路由，不是必要条件。',ref:'help.aliyun.com/zh/ack/best-practices/use-ingresses-to-implement-gray-release'},
  {id:'rel09',module:'发布与部署策略',type:'single',question:'以下关于"零停机发布（Zero-Downtime Deployment）"的实现前提，哪一项描述最准确？',options:['只要使用了 Docker 容器就天然零停机，不需要额外机制','应用需要满足健康检查就绪（readinessProbe/存活 livenessProbe）、优雅终止（preStop + terminationGracePeriodSeconds）、流量在版本间平滑切换（滚动/蓝绿/灰度等），以及数据库变更采用向后兼容策略（Expansion/Contract 模式）才能做到真正零停机','只要设置 SLB 健康检查即可 100% 保证零停机，应用内部是否优雅关闭无所谓','零停机只取决于发布工具，与业务代码和数据库 schema 设计无关'],answer:[1],explanation:'零停机是一个系统性结果，需要四层协同：①Pod 就绪探针确保新 Pod 能接流量才被加入端点、存活探针保障故障重建；②优雅终止确保正在处理的请求在 shutdown 之前能完成（preStop 睡眠+drain 连接）；③发布策略保证老版本不会被一下子全干掉；④DB schema 采用先扩后缩的两阶段变更，避免新老版本读写字段不匹配。其余选项均片面地把零停机归因于某一单点，会在生产中踩坑。',ref:'help.aliyun.com/zh/ack/best-practices/zero-downtime-deployment'},
  {id:'rel10',module:'发布与部署策略',type:'multi',question:'在 ACK 中使用 Deployment 进行滚动发布后，关于 `kubectl rollout` 命令与 revision 历史，下列说法正确的是？',options:['`kubectl rollout status deployment/<name>` 可以实时查看滚动发布进度与最终是否成功，常用于流水线中等待发布完成','`kubectl rollout history deployment/<name>` 可以查看历次 revision 的 CHANGE-CAUSE，有助于审计每次变更的原因','`kubectl rollout undo deployment/<name> --to-revision=N` 可以将 Deployment 回退到指定第 N 个历史 revision，回退的本质是把 ReplicaSet 切回该版本对应的模板','为了磁盘节省，应把 Deployment 的 `.spec.revisionHistoryLimit` 设为 0，这样回滚速度最快'],answer:[0,1,2],explanation:'A 正确，rollout status 会阻塞到最小可用副本满足或失败，是 CI/CD 流水线同步等待发布结束的标准用法；B 正确，rollout history 列出所有保留 revision 及其变更注释（change-cause），复盘时可快速定位变更来源；C 正确，rollout undo 是官方推荐的声明式回滚方式，其底层切换旧 ReplicaSet 与滚动发布走的是同一套 RollingUpdate 逻辑，也满足零停机；D 错误，revisionHistoryLimit=0 会清空所有历史快照，一旦线上出现问题将无法通过 rollout undo 回溯，生产环境通常建议保留 10 左右以便快速回滚。',ref:'help.aliyun.com/zh/ack/product-overview/deployment'},
  {id:'rel11',module:'发布与部署策略',type:'single',question:'某团队在 ACK 上未接入 ASM，但希望通过 Nginx Ingress 的注解实现灰度发布：只要请求头携带 `x-canary: always` 就路由到新版 Canary Service，其余走主 Stable Service。应使用以下哪组注解？',options:['`nginx.ingress.kubernetes.io/canary: "true"` 配合 `nginx.ingress.kubernetes.io/canary-by-header: x-canary` 与 `nginx.ingress.kubernetes.io/canary-by-header-value: always"`','仅靠 `nginx.ingress.kubernetes.io/rewrite-target` 注解即可完成灰度','设置 `nginx.ingress.kubernetes.io/ssl-redirect: "true"` 就会自动启用灰度','Nginx Ingress 不支持灰度，必须升级到 ASM 才能做任何灰度'],answer:[0],explanation:'Nginx Ingress 的 Canary 注解是 ACK 官方文档中实现灰度发布的轻量方案：为灰度版本单独建一个同名 Host 的 Ingress，加上 canary:true 声明其为灰度入口，再通过 canary-by-header + canary-by-header-value 指定按特定请求头路由。B 的 rewrite-target 只做路径重写；C 的 ssl-redirect 只是强制 HTTPS；D 错误，Nginx Ingress 支持基于权重、Cookie、Header 三种灰度方式，无需依赖服务网格。',ref:'help.aliyun.com/zh/ack/best-practices/use-ingresses-to-implement-gray-release'},
  {id:'rel12',module:'发布与部署策略',type:'multi',question:'关于云效 Flow 中"灰度发布阶段（Gray Release Stage）"的能力与用法，以下哪些说法是正确的？',options:['Flow 可对接 ACK/ECS/SAE/函数计算等多种发布目标，在同一流水线中先"部署到金丝雀节点/小比例节点"→人工或自动化确认→再"全量部署剩余节点"，实现平台无关的灰度工作流','灰度阶段支持"人工审批门禁"与"自动门禁"两种推进方式：自动门禁可结合云监控/Prometheus 指标（错误率、延迟、成功率）在观察窗口达标后自动进入全量，否则自动回滚','Flow 的灰度阶段能与钉钉审批/消息通知打通：灰度放量前 @ 值班负责人在群卡片上点击确认，做到发布决策的审计留痕','灰度阶段一旦创建就无法回滚，若出现问题必须手动 SSH 登录机器逐个修改'],answer:[0,1,2],explanation:'A 正确，Flow 的发布阶段是跨计算平台的一等公民，ACK/ECS/SAE/FC 都支持灰度+全量的编排；B 正确，自动门禁是 Flow 区别于传统流水线的关键能力，结合观测指标实现无人值守渐进式交付，失败自动回滚；C 正确，钉钉审批卡片集成是官方原生能力，审批记录同时可作为变更管理的合规依据；D 错误，Flow 的灰度阶段内置"回滚"动作按钮，支持一键切回上一稳定版本，并同步执行配置、代码、版本的整体回滚，无需手工操作机器。',ref:'help.aliyun.com/zh/devops/user-guide/gray-release'},
  {id:'rel13',module:'发布与部署策略',type:'multi',question:'某团队制定了发布后"三窗口监控"制度，并要求所有版本不可变。关于该制度的内容与目的，下列哪些说法是正确的？',options:['第一窗口：冒烟 5 分钟窗口，重点关注错误率、HTTP 5xx、核心接口 P99 延迟、Pod 重启等"立即故障"信号，若异常立即回滚','第二窗口：小比例放量 30 分钟窗口（灰度或影子阶段），重点关注业务指标（转化率、下单成功率、支付成功率）与长周期错误（内存泄漏、慢 SQL、连接池耗尽）','第三窗口：全量发布 2 小时窗口，覆盖一次完整的业务高峰或任务调度周期，观察容量水位、依赖方告警、上下游兼容性','配合"版本不可变"原则，三窗口若发现问题一律重建新版本再修复，绝不允许原地修改正在运行的 Pod / 覆盖镜像 tag，保证每个观察窗口与版本快照一一对应'],answer:[0,1,2,3],explanation:'A 是"冒烟窗口"，用于在发布刚结束的几分钟内发现致命问题，回滚成本最低；B 是"小比例观察窗口"，用于发现样本放大后才会暴露的性能与兼容性问题，覆盖长尾请求与资源消耗；C 是"全量观察窗口"，确保发布能扛住真实流量波峰与调度任务，避免白天发布、凌晨出问题的值班悲剧；D 补充了版本不可变与窗口监控的关系：只有快照是唯一且可追溯的，监控到异常时才能准确说清是哪个版本的问题，并走 rollout undo 或流水线一键回滚到对应快照。',ref:'help.aliyun.com/zh/devops/user-guide/release-monitoring-and-rollback'},
  {id:'rel14',module:'发布与部署策略',type:'single',question:'某团队在灰度发布前希望评估新版本在"上游调用延迟升高 2 秒"或"数据库 20% 请求返回超时"等异常场景下的表现，以验证熔断、降级、重试等韧性机制是否生效。应使用以下哪种发布验证手段？',options:['只跑单元测试即可覆盖所有异常路径','在 ASM 中使用故障注入（Fault Injection）能力：在 VirtualService 中对目标服务设置 delay（延迟）与 abort（中止/返回指定状态码）规则，灰度环境模拟异常再观察系统行为','直接在线上全量环境执行 kill -9 随机杀进程','依赖人工点击页面看看是否报错'],answer:[1],explanation:'ASM 的故障注入（delay 延迟注入、abort 错误注入）是发布前混沌工程式韧性验证的官方能力，可以在不修改一行业务代码的前提下精确模拟上游慢、下游不可用、超时等场景，验证新版本在异常条件下的熔断、重试、降级与监控告警是否按预期工作。A 单元测试无法覆盖分布式链路；C 在生产全量杀进程过于粗暴会影响用户；D 人工点击覆盖面极低且不可复现。',ref:'help.aliyun.com/zh/asm/user-guide/fault-injection'},

  // ========== 7. 微服务与服务治理 mse01~20（9 单 + 9 多 + 2 判） ==========
  {id:'mse01',module:'微服务与服务治理',type:'single',question:'关于 MSE 注册配置中心（Nacos 托管版）的协议兼容性，下列哪种说法是错误的？',options:['Nacos 2.x 默认使用 gRPC 长连接进行服务发现与配置监听，较 1.x HTTP 长轮询在海量连接下更省资源','MSE Nacos 仍支持以 HTTP 1.x 长轮询方式监听配置变更以兼容老版本 SDK','MSE 注册配置中心实例仅兼容 Nacos 协议，无法供 Eureka、ZooKeeper 客户端接入','MSE 提供 Eureka、ZooKeeper 协议兼容能力，可在不修改业务代码的情况下把自建 Eureka / ZooKeeper 集群平滑迁移到 MSE'],answer:[2],explanation:'MSE 注册配置中心除原生 Nacos 外，官方还提供 Eureka 与 ZooKeeper 协议兼容接入模式，迁移时只需要把注册中心地址指向 MSE 即可，无需改代码。A/B 描述的是 Nacos 2.x 通信演进：gRPC 长连接取代 HTTP 长轮询，显著降低大量客户端长连接带来的 CPU 与连接数开销，但为了兼容老 SDK，1.x HTTP 长轮询接口依旧保留。D 正是 MSE 官方宣传的"零代码迁移"卖点。',ref:'help.aliyun.com/zh/mse/product-overview/managed-registry-and-configuration-center'},
  {id:'mse02',module:'微服务与服务治理',type:'single',question:'某大型集团下有 10 个业务线，需要在同一套 MSE Nacos 实例中做到"业务线 A 看不到业务线 B 的服务与配置"，应使用 Nacos 的哪一层级做隔离？',options:['Group（分组）','DataId（数据 ID）','Namespace（命名空间）','Cluster（集群）'],answer:[2],explanation:'Nacos 的三层资源模型从大到小是 Namespace → Group → DataId/Service，其中 Namespace 是强隔离边界：不同 Namespace 下的服务、配置互相不可见，且 SDK 侧可通过 namespaceId 区分环境（如 dev/test/prod）或业务租户。Group 只是同一 Namespace 内的弱逻辑归类，无法做租户级隔离；DataId 是单个配置的粒度；Cluster 是服务实例下的二级分组，用于机房或版本区分，不具备配置与服务的租户隔离能力。',ref:'help.aliyun.com/zh/mse/user-guide/namespace-isolation'},
  {id:'mse03',module:'微服务与服务治理',type:'multi',question:'关于 MSE Nacos 配置中心的高级能力，以下说法正确的是？',options:['MSE Nacos 支持基于 KMS 的配置加密能力：对 DataId 以 -enc 结尾或开启加密开关的配置，敏感值落盘时密文存储，读取时由 SDK 侧自动解密，避免数据库与磁盘泄露明文','配置灰度（Beta 推送）允许先把新配置推送给一小部分打上 Beta 标签的实例验证效果，验证通过后再全量推送，从而降低配置变更事故面','配置版本回溯能力可以一键把某个 DataId 回滚到指定历史版本，同时保留每次变更的操作人与时间，可用于审计与事故恢复','Nacos 配置一旦发布即无法撤销，需要运维手动把备份配置重新发布'],answer:[0,1,2],explanation:'A 正确：MSE Nacos 与 KMS 密钥管理服务深度集成，支持单配置加密，数据库、控制台、落盘文件中均为密文，只有合法 SDK 通过 KMS 解密后才能在内存中读取明文，满足等保合规；B 正确：Beta 推送是 MSE Nacos 区别于开源版的核心增强，可以先把新配置推给少数带 Beta tag 的客户端灰度验证，避免一次性全量发布造成雪崩；C 正确：MSE Nacos 控制台内置历史版本对比与一键回滚，每一份配置的每次变更都会保留快照，并记录发布人、发布时间与发布原因，便于事后审计追溯；D 错误：与 C 相矛盾，MSE Nacos 自带版本快照与回滚，不需要运维手工备份再发布。',ref:'help.aliyun.com/zh/mse/user-guide/use-configuration-management'},
  {id:'mse04',module:'微服务与服务治理',type:'single',question:'阿里云微服务引擎 MSE 中，以下哪一组件提供了开箱即用的 Nacos 注册中心 + 配置中心托管能力，支持命名空间隔离、配置加密、配置版本回溯、配置灰度推送？',options:['MSE 云原生网关','MSE 注册配置中心（Nacos 托管版）','MSE 服务治理（标签路由、全链路灰度、流量防护）','MSE ZooKeeper 独享版'],answer:[1],explanation:'MSE 注册配置中心提供 Nacos（同时支持 Eureka/ZooKeeper 协议兼容）托管版实例，直接对应题干能力。A 是南北向七层网关；C 是叠加在应用接入之上的治理能力（与注册中心解耦）；D 只有 ZooKeeper，不含 Nacos。',ref:'help.aliyun.com/zh/mse/product-overview/what-is-mse'},
  {id:'mse05',module:'微服务与服务治理',type:'multi',question:'关于 Nacos 配置变更的监听机制，下列有关"HTTP 长轮询"和"gRPC 长连接"的对比，正确的是？',options:['Nacos 1.x 时代采用 HTTP 长轮询：客户端每隔 30 秒发起一次 HTTP 请求挂起，30 秒内若配置有变更立即返回，无变更则 30 秒超时后再次发起，实现"准实时 + 低轮询开销"的折中','Nacos 2.x 引入 gRPC 长连接：客户端与服务端建立一条 TCP 复用连接，配置变更由服务端主动 Push，进一步降低 HTTP 建连开销与服务端线程占用','gRPC 模式相比 HTTP 长轮询，在 10 万级客户端同时在线时服务端 C10K 压力明显下降，更适合超大集群部署','两种机制互斥：接入 Nacos 2.x 后必须把所有客户端升级到 gRPC SDK，老版本 HTTP SDK 将完全无法工作'],answer:[0,1,2],explanation:'A 正确：长轮询（Long Polling）是 Nacos 1.x 的核心机制，它解决了传统短轮询"频繁空请求"的缺点，同时保留了 HTTP 协议对防火墙友好的优势；B 正确：Nacos 2.x 的最大演进就是引入 gRPC 双向流式通信，服务端真正"主动推送"配置与注册变化，推拉延迟显著降低；C 正确：gRPC 多路复用把大量客户端从"每条连接一个线程"里解放出来，Nacos 2.x 单机支持的客户端数相较 1.x 提升 10 倍以上，是 MSE 在超大规模下稳定承载的关键；D 错误：Nacos 2.x 服务端对 1.x SDK 做了完整向下兼容，新老 SDK 可以混合接入，只是老 SDK 走 HTTP 长轮询，新 SDK 走 gRPC，不存在升级新版本后老客户端无法工作的情况。',ref:'help.aliyun.com/zh/mse/product-overview/nacos-2x'},
  {id:'mse06',module:'微服务与服务治理',type:'single',question:'关于 MSE 云原生网关替代传统 K8s Nginx Ingress 的优势，以下说法最不准确的是？',options:['MSE 云原生网关天然对齐 K8s Gateway API 与 Ingress CRD，可零改造接管现有 Nginx Ingress 流量','MSE 云原生网关集成了 JWT/OIDC 认证、IP 黑白名单、CORS、限流、WAF 防护等常用能力，无需像 Nginx 一样依赖多个插件与 ConfigMap 调优','MSE 云原生网关支持与 MSE 注册配置中心、ACK ASM 服务网格深度联动，可直接按服务名 + 标签做路由，性能与 Nginx Ingress 相比较高','MSE 云原生网关必须搭配 MSE 注册配置中心才能使用，无法直接对接普通 K8s Service'],answer:[3],explanation:'MSE 云原生网关（Cloud-Native Gateway）是阿里云推出的下一代七层网关，定位于替代社区 Nginx Ingress：A 正确，它兼容 Ingress/Gateway API 资源，存量 Ingress 可以直接切换类名无改造迁移；B 正确，认证、黑白名单、CORS、限流、WAF 集成都是控制台级一键开关，不需要像 Nginx 一样手写大量注解或 Lua 插件；C 正确，MSE 云原生网关基于 Envoy + Go 扩展实现，RPS、HTTPS 握手、配置热加载延迟等官方基准优于社区 Nginx Ingress，并能直接从 Nacos/ASM 控制面拉取服务列表和标签路由。D 错误，MSE 云原生网关同样支持直接对接普通 K8s Service、SLB、ECS 地址、DNS、OSS Bucket 等多种后端类型，并不强制依赖 MSE 注册配置中心。',ref:'help.aliyun.com/zh/mse/product-overview/cloud-native-gateway'},
  {id:'mse07',module:'微服务与服务治理',type:'multi',question:'MSE 云原生网关提供了丰富的南北向流量治理能力，以下哪些属于其默认支持的能力？',options:['基于请求路径、Host、Header、Query、Method 等多维度的精细化路由匹配，以及按权重做流量切分的灰度路由','JWT/OIDC 认证插件：网关层校验前端传入的 Access Token，不合法直接在网关层拦截，避免无效请求打到后端服务','基于 IP 的黑白名单、CORS 跨域配置，以及与阿里云 WAF 产品集成的 Web 应用防护能力','基于网关实例内日志自动生成 MySQL 慢查询报告并自动优化 SQL 索引'],answer:[0,1,2],explanation:'A 正确：MSE 云原生网关路由规则支持 HTTP 七层几乎全部匹配维度，并能按权重把同一路径的流量分发到后端多个版本（如 v1 90% + v2 10% 金丝雀发布）；B 正确：JWT/OIDC 是网关层的官方内置插件，可把认证逻辑与业务解耦，网关校验签名/过期/claims，通过后才转发；C 正确：IP 黑白名单、CORS 均为控制台一键配置，并且 MSE 云原生网关与阿里云 WAF 3.0 做了深度打通，入站流量可直接由 WAF 做 OWASP Top 10 防护；D 错误：网关层位于 L7 入口，与 DB 的慢查询、索引优化属于完全不同的技术栈，慢 SQL 分析应由 ARMS 应用监控或 DMS/DAS 完成，不属于网关的职责。',ref:'help.aliyun.com/zh/mse/user-guide/cloud-native-gateway-routing'},
  {id:'mse08',module:'微服务与服务治理',type:'single',question:'MSE 服务治理中的"标签路由（Tag-based Routing）"和"全链路灰度泳道（Lane）"的区别，下列哪一项最准确？',options:['两者完全等价，只是不同文档中的命名差异','标签路由是单机级的本地流量转发规则；泳道是跨集群的物理网络隔离','标签路由是基于请求标签（Header/参数）把一次调用指向匹配 Tag 的单服务实例；泳道（Lane）则把一组版本相同的服务实例组成"泳道"，请求携带泳道标记后整个调用链始终落在同一泳道内，实现多服务串联的全链路灰度','泳道仅适用于数据库层面的读写分离，与服务路由无关'],answer:[2],explanation:'标签路由是 MSE 治理中较基础的能力：为应用实例打 Tag（如 gray=v2），SDK 或 Agent 在发起一次 RPC/HTTP 调用时按规则把请求优先发给匹配 Tag 的实例，但它只管"一跳"，对于订单→库存→支付这种 3 跳链路，若未在每个节点都写转发规则就会出现"流量串泳道"问题。泳道 Lane 是 MSE 在标签路由之上发展出的全链路灰度能力：先定义"环境/泳道"，将同版本的一组服务归为同一泳道，SDK/Agent 在链路入口把泳道 ID 写入透传 Header，之后每一跳都会由治理 Agent 自动按泳道 ID 选同泳道的实例，即使中间夹杂消息队列、定时任务也能继续透传，真正实现端到端的"同泳道闭环"。A 命名不同、能力也不同；B 错在物理隔离，泳道仍是逻辑隔离；D 与数据库读写分离无关。',ref:'help.aliyun.com/zh/mse/user-guide/lane-based-gray-release'},
  {id:'mse09',module:'微服务与服务治理',type:'multi',question:'关于 MSE 服务治理中的限流、熔断、离群摘除、热点参数限流，以下说法正确的是？',options:['限流：MSE 兼容 Sentinel 规则模型，支持按 QPS、并发线程数、基于请求耗时等维度限流，保护下游服务不被突发流量压垮','熔断：当下游服务连续出现异常比例或慢调用比例超过阈值时，自动触发熔断器打开，在一段时间内快速失败返回降级结果，避免故障沿调用链逐级放大','离群摘除（Outlier Detection）：MSE Agent 会定期统计每个实例的错误率与平均 RT，当某实例显著异常时将其从可用列表中暂时摘除，恢复后再自动加回，解决"少数坏实例拉低整体成功率"的问题','热点参数限流：针对某一接口中出现频率极高的特定参数值（如某个热点商品 ID、某个用户 ID）单独加限流阈值，避免"大 V 发微博"类热点把整个服务打挂'],answer:[0,1,2,3],explanation:'A 正确：MSE 治理的限流能力底层与 Sentinel 规则体系 100% 兼容，QPS 限流、并发数限流、慢调用比例限流都是一等公民，迁移用户只需将控制台切换到 MSE 即可；B 正确：熔断是服务雪崩的克星，常见策略包括异常比例、异常数、慢调用比例三种，熔断打开后进入快速失败窗口，窗口过半后进入半开探测状态，成功则关闭、失败则继续打开，是经典"熔断器三状态"模型；C 正确：离群摘除面向实例维度，是 MSE 在客户端负载均衡层做的增强，其效果类似 Istio 的 OutlierDetection，对于一个集群中偶发的慢/坏节点特别有效；D 正确：热点参数限流是 Sentinel/MSE 的差异化能力，相比简单"接口级别限流"，它可以精确到参数级别，例如"商品详情接口整体不限流，但商品ID=123 这个爆款每秒最多 1000 QPS"，特别适合秒杀、热点话题等场景。',ref:'help.aliyun.com/zh/mse/user-guide/flow-control-and-circuit-breaking'},
  {id:'mse10',module:'微服务与服务治理',type:'single',question:'关于"单机限流"与"集群限流"的区别，以下描述最准确的是？',options:['单机限流：在每个应用实例本地独立计数限流（如每个实例限 100 QPS），实例数越多整体上限越高；集群限流：由独立的限流服务统一计数（如整个服务无论多少实例都只允许 500 QPS），保证总量精确','单机限流只能用在单机版应用；集群限流只能用在分布式应用','单机限流的精度高于集群限流','集群限流是基于硬件做的限流，单机限流是基于软件做的限流'],answer:[0],explanation:'A 准确描述了二者的核心差异：单机限流按实例各自计数，总量 = 单机阈值 × 实例数，当实例弹性扩缩容时总量不可控；集群限流通过集中式 Token Server（MSE 内置）统一发令牌，总量严格等于设定阈值，精度更高但会多一次 RPC。B 错：单机/集群不是"单机/分布式应用"的区别，分布式应用里照样可以用单机限流；C 反了，集群限流精度更高；D 错，两者都是软件实现，只是计数位置不同。MSE 的 Sentinel 兼容规则里，单机限流对应"流控效果"本地规则，集群限流需要开启集群模式并绑定 Token Server。',ref:'help.aliyun.com/zh/mse/user-guide/cluster-flow-control'},
  {id:'mse11',module:'微服务与服务治理',type:'multi',question:'关于 ASM（阿里云服务网格，兼容 Istio）的 Sidecar 自动注入，以下说法正确的是？',options:['开启 Sidecar 自动注入的常见做法是给目标 Namespace 打上 `istio-injection=enabled` 标签，之后该 Namespace 下新建 Pod 时 ASM 的 Mutating Webhook 会自动为其注入 envoy sidecar 容器与 init 容器','Sidecar 注入的 init 容器（istio-init）主要负责配置 iptables 规则，把进出业务容器的流量透明劫持到 envoy，从而在不修改业务代码的前提下实现流量治理','已经存在的 Pod 只要打上标签就会自动完成 Sidecar 注入，无需重建','可以通过在 Pod 上设置 `sidecar.istio.io/inject: "false"` 注解，为特定 Pod 单独豁免自动注入（如数据库、日志采集组件等不宜加 sidecar 的工作负载）'],answer:[0,1,3],explanation:'A 正确：Namespace 级别 istio-injection=enabled 是官方推荐的默认注入方式，ASM 还支持基于 Pod 注解的细粒度开关；B 正确：istio-init 用 iptables 在 Pod netns 中把 15001/15006 等入出站端口转发给 Envoy，实现对业务透明的流量劫持，这也是"零代码侵入治理"的基础；C 错误：Mutating Webhook 只在 Pod 创建时介入，对已运行的 Pod 不会改动 iptables，因此开启注入后必须重建 Pod（滚动重启 Deployment）才能生效，这是 Istio/ASM 的常见陷阱；D 正确：sidecar.istio.io/inject=false 是官方豁免注解，常用于 StatefulSet 里的 MySQL/Redis、Job、Logtail 等不希望被 sidecar 劫持流量或不想多占资源的组件。',ref:'help.aliyun.com/zh/asm/user-guide/sidecar-injection'},
  {id:'mse12',module:'微服务与服务治理',type:'single',question:'在 ASM/Istio 中，需要对 `reviews` 服务配置"90% 流量到 v1 版本，10% 流量到 v2 版本"的权重路由，以及"请求头 x-test: on 时全部走 v2 版本"的 Header 优先路由，应使用哪一 CRD 定义这些规则？',options:['Gateway','VirtualService','DestinationRule','Sidecar'],answer:[1],explanation:'VirtualService 是 Istio/ASM 流量治理的"路由规则定义中心"：规则匹配顺序从上到下生效，可以先写基于 Header/Cookie/URI 的精确匹配分支（x-test:on → v2 subset），再写默认的 90%/10% 权重路由分支。A 的 Gateway 只负责网格入口的 L4/L7 监听和证书，不做权重路由；C 的 DestinationRule 负责定义版本 Subset、负载均衡策略、熔断和 mTLS，不负责匹配条件，要先有 DestinationRule 定义 subset，VirtualService 才能引用 subset；D 的 Sidecar 用来裁剪 Sidecar 的配置范围，与题意无关。',ref:'help.aliyun.com/zh/asm/user-guide/virtual-service'},
  {id:'mse13',module:'微服务与服务治理',type:'multi',question:'下列 ASM/Istio 的 DestinationRule 能力与典型用法，说法正确的是？',options:['DestinationRule 的 subsets 字段可以根据 Pod labels 将同一 Service 划分为多个版本子集，如 v1/v2/canary，供 VirtualService 做权重和条件路由','可以在 DestinationRule 的 TrafficPolicy 中配置连接池（ConnectionPool）与异常点检测（OutlierDetection），实现客户端侧的熔断与离群摘除','可以在 DestinationRule 中配置 mTLS 模式：ISTIO_MUTUAL 表示使用 Istio 颁发的证书做双向 TLS，配合 PeerAuthentication 实现服务间加密通信','DestinationRule 可以直接定义 HTTP 请求头匹配与 URL 重写规则'],answer:[0,1,2],explanation:'A 正确：Subset 是 DestinationRule 最核心的用途，通过 version/gray/canary 等标签对 Endpoint 切片，VirtualService 再按 subset 路由，是 ASM 灰度发布的基础；B 正确：连接池（TCP/HTTP 最大连接、最大请求数、最大等待队列等）+ OutlierDetection（连续 5xx 比例、BaseEjectionTime）共同构成了"客户端熔断+离群摘除"机制，无需应用集成 Sentinel 即可获得治理能力；C 正确：DestinationRule.trafficPolicy.tls.mode = ISTIO_MUTUAL 是客户端主动发起 mTLS 的标准写法，与服务端 PeerAuthentication 的 STRICT/PERMISSIVE/DISABLE 三模式配合完成全网 mTLS 协商；D 错误：请求头匹配、URL 重写、超时、重试、Mirror、Fault Injection 等行为路由能力都定义在 VirtualService 中，DestinationRule 只处理"选好目标后如何连接/如何划分 subset"，不处理路由条件。',ref:'help.aliyun.com/zh/asm/user-guide/destination-rule'},
  {id:'mse14',module:'微服务与服务治理',type:'multi',question:'关于 ASM 的流量镜像（Traffic Mirror / Shadow）与故障注入（Fault Injection），以下说法正确的是？',options:['流量镜像可以把生产环境真实流量的一份副本异步发送给新版服务（影子服务），新版返回结果会被丢弃，因此镜像流量不会影响真实用户，常用于上线前用真实流量做回归、性能与兼容性验证','故障注入支持两类：delay（向请求中注入额外延迟，模拟慢依赖、网络抖动）和 abort（直接返回指定 HTTP 状态码，模拟下游不可用），二者都定义在 VirtualService 的 fault 字段','故障注入只能影响特定比例的请求，无法做到 100% 注入','镜像流量的目标若超时或错误，会触发用户主请求的回滚'],answer:[0,1],explanation:'A 正确：Mirror 是 ASM/Istio 中非常有价值的"先线上验证再发版"能力，主请求依旧走稳定版本，镜像流量是 Fire-and-forget，不会因为影子服务报错影响用户，是影子模式发布的基石；B 正确：Istio Fault Injection 官方就两种动作：HTTPFault 下 delay 与 abort，可以按百分比或 Header 条件精确命中，是灰度发布前的韧性测试利器；C 错误：fault.percent 可以设为 100，完全可以在测试环境把特定路由的所有请求全部注入故障验证降级链路；D 错误：镜像流量本质是"额外复制一份出去"，它的成功/失败不影响主链路响应，因此不会触发用户请求失败、也不会自动回滚，主链路是否升级需要看对镜像流量的监控比对结果。',ref:'help.aliyun.com/zh/asm/user-guide/traffic-mirroring'},
  {id:'mse15',module:'微服务与服务治理',type:'single',question:'ASM/Istio 的 mTLS（双向 TLS）支持 STRICT / PERMISSIVE / DISABLE 三种 PeerAuthentication 模式，关于它们的描述，下列哪一项是错误的？',options:['STRICT 模式：服务端只接受携带 mTLS 证书的请求，所有明文/非证书请求会被拒绝，用于生产环境"全网加密"的终态','PERMISSIVE 模式：服务端同时接受明文与 mTLS 两种请求，用于在逐步开启 mTLS 的过渡阶段，避免一刀切造成未注入 Sidecar 的服务无法访问','DISABLE 模式：服务端强制拒绝 mTLS 请求，只能用明文通信，通常用于调试或与非网格外部系统通过明文对接','三种模式的切换会立即对 Namespace 下所有已注入 Sidecar 的 Pod 的业务容器生效，无需控制面下发任何 XDS 配置'],answer:[3],explanation:'STRICT/PERMISSIVE/DISABLE 是 Istio 官方命名的三态：A、B、C 分别对应它们的标准用途与行为，特别要记住 PERMISSIVE 是"渐进式开启 mTLS"的关键过渡态，官方推荐的上线步骤是全局 PERMISSIVE → 观测 Grafana 中 mTLS 占比 → 逐个 Namespace 切 STRICT，最终实现全网 mTLS。D 错误：PeerAuthentication 是 CRD 资源，变更后由 istiod（ASM 控制面）通过 XDS 协议将新的 TLS 规则推送给每个 Envoy Sidecar，业务容器本身并不处理 TLS，因此 D 描述的"无需控制面下发 XDS"与事实相反。',ref:'help.aliyun.com/zh/asm/user-guide/mutual-tls'},
  {id:'mse16',module:'微服务与服务治理',type:'multi',question:'MSE/ASM 与阿里云可观测体系的对接，下列说法正确的是？',options:['MSE/ASM 均可与 ARMS 应用监控对接：自动上报调用链（SkyWalking/OpenTelemetry 格式）、生成服务拓扑图，并在控制台上直接查看每个接口的 P99/错误率/RPS、慢 SQL、异常堆栈','MSE/ASM 均可将访问日志（Access Log）与 Sidecar 业务日志投递到 SLS 日志服务（通过 Logtail 采集器或 ASM 内置日志开关），用于审计、排障与 SIEM 对接','MSE/ASM 均可把指标（QPS、RT、4xx/5xx、Sidecar 资源使用、Pilot/XDS 推送耗时）暴露给 Prometheus（托管版或自建），再由 Grafana 出官方大盘','MSE/ASM 的可观测能力只能输出到阿里云产品，无法对接开源方案（如 Jaeger、Grafana Loki）'],answer:[0,1,2],explanation:'A 正确：ARMS 应用监控是 MSE/ASM 官方推荐的 APM，在控制台"接入应用监控"开关打开后，无需修改代码即可获得完整调用链 + 拓扑 + 上下游依赖，是日常排障、容量评估的核心入口；B 正确：MSE 云原生网关和 ASM Sidecar 的 Access Log 均支持一键投递到 SLS 指定 Project/Logstore，SLS 内置的 Envoy 访问日志仪表盘开箱即用，也可以通过 SLS 订阅投递到自建 SIEM；C 正确：ASM 控制面与 Sidecar、MSE 网关与治理 Agent 都暴露了标准 /metrics 端点，阿里云 Prometheus 托管版可以通过 CRD（ServiceMonitor/PodMonitor）一键抓取，并附带官方 Grafana Dashboard；D 错误：MSE/ASM 上报的 Trace/Metric/Log 遵循 OpenTelemetry、Prometheus Exposition、结构化 JSON 等行业标准，可以直接对接 Jaeger、Loki、Tempo、Grafana 等任何开源可观测组件，并不锁定阿里云生态。',ref:'help.aliyun.com/zh/asm/user-guide/observability'},
  {id:'mse17',module:'微服务与服务治理',type:'single',question:'关于微服务体系中的"南北向流量"与"东西向流量"，以下描述最准确的是？',options:['南北向流量 = 客户端 → 网关 → 集群内部服务 的入口流量；东西向流量 = 集群内部服务之间互相调用的流量。MSE 云原生网关 / ASM Gateway 主要处理南北向；Sidecar 代理 + VirtualService/DestinationRule 主要治理东西向','南北向流量 = 跨机房流量；东西向流量 = 同机房流量','南北向流量 = 只读请求；东西向流量 = 写请求','南北向流量 = 数据库同步流量；东西向流量 = 缓存同步流量'],answer:[0],explanation:'在微服务/服务网格术语中，南北向（North-South）和东西向（East-West）是流量方向的经典划分：A 是行业标准定义，网关层（MSE 云原生网关、ASM Gateway、Nginx Ingress）负责把"外部用户"流量接到集群内部，属于典型南北向；服务之间的 RPC/HTTP 调用属于集群内部横向流通，即东西向，由 Sidecar + 治理规则（标签路由、泳道、熔断、重试、mTLS 等）负责。其他选项都是对"方向"二字的字面错误解读，与业界标准定义无关。这个划分在选择产品时很重要：南北向能力看网关产品，东西向能力看服务网格与 MSE 服务治理。',ref:'help.aliyun.com/zh/asm/product-overview/what-is-asm'},
  {id:'mse18',module:'微服务与服务治理',type:'multi',question:'关于 ASM Gateway（服务网格入口网关）与 MSE 云原生网关的定位与差异，下列说法正确的是？',options:['ASM Gateway 是 Istio IngressGateway 的托管实现，深度绑定 ASM 控制面：同一套 Gateway + VirtualService + DestinationRule 同时表达入口路由与网格内部路由，适合"入口-网格一体化治理"的场景','MSE 云原生网关定位更偏向"通用入口网关"，除了对接 ASM/ACK 工作负载，还可直接代理 ECS、SLB、OSS、函数计算等非 K8s 后端，适合后端形态异构的企业统一入口','两者都支持 JWT 认证、限流、WAF 集成、HTTPS 证书管理等常见南北向治理能力，只是生态绑定深度不同','两者功能完全相同，只是计费方式不同，任选其一即可'],answer:[0,1,2],explanation:'A 正确：ASM Gateway 本质就是托管的 Istio IngressGateway Pod，它和网格内部 Sidecar 共享同一个 istiod 控制面，VirtualService 里只要把 gateways 字段加上 mesh + ingressgateway 就能同时定义入口和网格内路由，入口 Header/泳道标签一路到底，非常契合全链路灰度；B 正确：MSE 云原生网关是阿里云自研的独立托管网关，后端类型覆盖面更广——ACK、Nacos、ECS、SLB、OSS、FC、DNS 都能直接加后端，尤其适合存在大量存量 ECS 微服务的企业用一个网关统一接所有南北向流量；C 正确：两者在基础南北向能力上的重合度很高，JWT、OIDC、IP 黑白名单、CORS、限流、WAF 3.0 集成、Cert 证书管理都是各自控制台的标准功能；D 错误：功能重叠但绝非相同，选型上通常建议"以 ASM 为核心网格、且后端大多在 ACK 内 → ASM Gateway；后端异构，需要覆盖 ECS/OSS/FC → MSE 云原生网关"，同时两者也可以组合使用，MSE 网关在外层做统一接入，内层再用 ASM Gateway 做泳道灰度。',ref:'help.aliyun.com/zh/mse/best-practices/mse-gateway-vs-asm-gateway'},
  {id:'mse19',module:'微服务与服务治理',type:'judge',question:'在 ASM 服务网格中，只要 Namespace 开启了 Sidecar 自动注入，已经运行中的 Pod 就会立即被注入 Envoy Sidecar 并自动开启 mTLS，无需执行滚动重启。',options:['正确','错误'],answer:[1],explanation:'Istio/ASM 的 Sidecar 自动注入由 K8s MutatingAdmissionWebhook 在 Pod 创建阶段介入，对已运行的 Pod 不会回溯修改 iptables 与容器；因此开启命名空间注入后，必须对 Deployment/StatefulSet 执行滚动重启（或重建 Pod）才能让新 Pod 携带 Sidecar。同样，变更 PeerAuthentication 的 mTLS 模式虽然不需要重启 Pod（通过 XDS 下发给 Sidecar），但如果 Pod 本身还没有 Sidecar，就不可能生效。题干"立即生效，无需重启"不成立。',ref:'help.aliyun.com/zh/asm/user-guide/sidecar-injection'},
  {id:'mse20',module:'微服务与服务治理',type:'judge',question:'MSE 服务治理的"泳道（Lane）全链路灰度"能力，在请求进入第一个服务打上泳道 Tag 后，后续经过的 RPC、MQ 消息、定时任务、Redis 读写链路都能自动透传泳道标识，从而保证整条调用链都落在同一版本泳道内。',options:['正确','错误'],answer:[0],explanation:'MSE 泳道（Lane）的核心差异化能力就是"跨多种调用形态的全链路透传"：入口网关通过 Header/规则匹配写入泳道 ID 到 Baggage/透传字段后，MSE Agent 对 Dubbo/Spring Cloud/GRPC/HTTP 等 RPC、RocketMQ/Kafka 等消息队列、XXL-Job/定时任务、甚至常见的 Redis 缓存读写组件都做了自动埋点，使下游实例在消费消息或处理任务时仍能拿到上游泳道标识并继续在同泳道实例中调用下游，彻底避免了"入口进 v2 泳道 → MQ 消费到 v1 → 再调下游跑到 v1"的串泳道问题。题干描述的正是 MSE Lane 的标准能力，表述正确。',ref:'help.aliyun.com/zh/mse/user-guide/lane-based-gray-release'},
];

